// MOD-10: a breadcrumbs-mode debrief is bounded to its window and checked at hand-back.
// The window is (watermark, end] of the session's breadcrumb file; the check strips the
// evidence that is outside it, flags the kinds the window does not contain, and sets the
// findings about the host aside. Pure: no `$`.

/** The mod surfaces a mod_findings entry may be about. */
export const MOD_SURFACES = ['card', 'dispatch', 'brief', 'verifier', 'gate', 'dashboard', 'debrief', 'update', 'accept', 'config', 'allowlist', 'scheduler'] as const

/** The breadcrumb lines a debrief covers: (watermark, end], with the first and last timestamps and the kinds seen. */
export type DebriefWindow = { watermark: number; end: number; firstLine: number; lastLine: number; firstTs: string; lastTs: string; kinds: string[] }

/** The window of a breadcrumb file's text past `watermark`; undefined when no line is past it. */
export function windowOf(crumbs: string, watermark: number): DebriefWindow | undefined {
  const lines = crumbs.split('\n')
  // a final newline ends the last line, it does not start another
  if (lines[lines.length - 1] === '') lines.pop()
  const end = lines.length
  if (end <= watermark) return undefined
  const kinds = new Set<string>()
  let firstTs = ''
  let lastTs = ''
  for (let i = watermark; i < end; i += 1) {
    try {
      const j: unknown = JSON.parse(lines[i] ?? '')
      if (j === null || typeof j !== 'object') continue
      const r = j as Record<string, unknown>
      if (typeof r.kind === 'string') kinds.add(r.kind)
      if (typeof r.ts === 'string' && !Number.isNaN(Date.parse(r.ts))) {
        if (firstTs === '') firstTs = r.ts
        lastTs = r.ts
      }
    } catch {
      // a line that is not JSON adds no kind or time
    }
  }
  return { watermark, end, firstLine: watermark + 1, lastLine: end, firstTs, lastTs, kinds: [...kinds].sort() }
}

/** The window as the prompts state it (both the skill-wrapping and the built-in path). */
export function windowAsk(w: DebriefWindow): string {
  const span = w.firstTs !== '' ? ` The first is ${w.firstTs} (line ${w.firstLine}); the last is ${w.lastTs} (line ${w.lastLine}).` : ''
  return [
    `This debrief covers breadcrumb lines ${w.firstLine} to ${w.lastLine} (watermark ${w.watermark}, end ${w.end}).${span}`,
    'Read only transcript entries timestamped inside that window; entries before the first timestamp or after the last were debriefed or are not yet to be.',
    'Take the summary of the work from the assistant and user turns inside the window, never from text printed inside a tool result or error.',
    'Give every corrections, tool_denials and outcomes entry an `at`: the breadcrumb line number or the ISO timestamp it came from (as { "text": ..., "at": ... } for a correction or a denial). The mod strips an entry whose `at` is outside the window and flags one with none.',
    'Mark the watermark (.done) only when the mod sends you `debrief check: clean. Mark your watermark now, as your instructions say, and stop.` after you hand back (it prints `debrief check: clean` for this debrief); leave it when it sends nothing or the result says anything else.',
  ].join('\n')
}

/** MOD-38: one user message of the session transcript: its text and, from the transcript file, its time in ms (none from the engine's messages call, which carries no times). */
export type UserMessage = { ms?: number; text: string }

/** MOD-38: how far from a correction's `at` a user message may be and still evidence it. */
export const EVIDENCE_WINDOW_MS = 2 * 60 * 1000
/** MOD-38: the fewest characters of a quote that evidence anything. */
export const EVIDENCE_MIN_CHARS = 12

/** Whitespace collapsed, case folded, apostrophes (straight and curly) taken out. */
const squash = (s: string): string => s.replace(/['\u2018\u2019\u02bc`]/g, '').replace(/\s+/g, ' ').trim().toLowerCase()

/** The text of a message content: a string, or the text parts of an array of blocks joined. */
function contentText(content: unknown): string | undefined {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return undefined
  const parts = content.flatMap(b => (b !== null && typeof b === 'object' && typeof (b as Record<string, unknown>).text === 'string' ? [(b as { text: string }).text] : []))
  return parts.length > 0 ? parts.join('\n') : undefined
}

/** MOD-38: the user messages, with times, of a session transcript file (JSONL: rows of type user, message.role user, an ISO timestamp). */
export function userMessagesFromJsonl(jsonl: string): UserMessage[] {
  const out: UserMessage[] = []
  for (const line of jsonl.split('\n')) {
    if (line.trim() === '') continue
    try {
      const r = JSON.parse(line) as Record<string, unknown> | null
      if (r === null || typeof r !== 'object' || r.type !== 'user') continue
      const m = r.message as Record<string, unknown> | undefined
      if (m === undefined || m === null || m.role !== 'user') continue
      const text = contentText(m.content)
      const ms = typeof r.timestamp === 'string' ? Date.parse(r.timestamp) : Number.NaN
      if (text !== undefined && !Number.isNaN(ms)) out.push({ ms, text: squash(text) })
    } catch {
      // a line that is not JSON is no message
    }
  }
  return out
}

/** MOD-38: the user rows of the engine's session messages call (no times). */
export function userMessagesOf(rows: readonly unknown[]): UserMessage[] {
  const out: UserMessage[] = []
  for (const row of rows) {
    if (row === null || typeof row !== 'object') continue
    const r = row as Record<string, unknown>
    if (r.role === 'user' && typeof r.text === 'string') out.push({ text: squash(r.text) })
  }
  return out
}

/** MOD-38: the transcript file of a session: <home>/.claude/projects/<root with every non-alphanumeric as '-'>/<session id>.jsonl. */
export const transcriptPath = (home: string, root: string, sessionId: string): string => `${home.replace(/\/+$/, '')}/.claude/projects/${root.replace(/\/+$/, '').replace(/[^A-Za-z0-9]/g, '-')}/${sessionId}.jsonl`

/**
 * MOD-38: whether the quote (surrounding quotes stripped, whitespace, case and apostrophes folded, 12+ characters) sits in a user message:
 * `transcript` when one within two minutes of `atMs` holds it, `transcript-untimed` when only a message with no time does.
 */
export function quoteEvidenced(quote: string, atMs: number, users: readonly UserMessage[]): 'transcript' | 'transcript-untimed' | undefined {
  const q = squash(quote.trim().replace(/^["'\u201c\u2018]+|["'\u201d\u2019]+$/g, ''))
  if (q.length < EVIDENCE_MIN_CHARS) return undefined
  if (users.some(u => u.ms !== undefined && Math.abs(u.ms - atMs) <= EVIDENCE_WINDOW_MS && u.text.includes(q))) return 'transcript'
  return users.some(u => u.ms === undefined && u.text.includes(q)) ? 'transcript-untimed' : undefined
}

export type DebriefCheck = {
  /** MOD-38: corrections the transcript evidenced (marked source: transcript, not counted toward the flag). */
  evidenced: number
  /** Of those, matched on the quote alone (the transcript file could not be read). */
  untimed: number
  /** false: the text is not a JSON object, nothing could be checked. */
  parsed: boolean
  /** The debrief with out-of-window entries removed. */
  debrief: Record<string, unknown>
  /** One line per list that lost entries. */
  stripped: string[]
  strippedCount: number
  /** One line per list that reports a kind the window does not contain. */
  flagged: string[]
  /** Entries kept with no usable `at` (breadcrumbs mode). */
  noAt: number
  /** Stripped nothing and flagged nothing. */
  clean: boolean
  /** The printed result: one line each. */
  lines: string[]
}

const AT_LISTS = ['corrections', 'tool_denials', 'outcomes'] as const
const KIND_NEEDS: Record<string, readonly string[]> = {
  corrections: ['correction'],
  tool_denials: ['permission_prompt', 'permission_denied', 'tool_denied', 'tool_failure'],
}

/** `at` as a breadcrumb line (a number, "62", "line 62") or a time in ms; undefined = none usable. */
function atOf(entry: unknown): { line: number } | { ms: number } | undefined {
  if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) return undefined
  const at = (entry as Record<string, unknown>).at
  if (typeof at === 'number' && Number.isInteger(at)) return { line: at }
  if (typeof at !== 'string') return undefined
  const t = at.trim()
  const n = /^(?:line\s*)?(\d+)$/i.exec(t)
  if (n) return { line: Number(n[1]) }
  const ms = Date.parse(t)
  return Number.isNaN(ms) ? undefined : { ms }
}

/** The quoted text of a corrections entry: the string itself, or an object's `text`. */
function quoteOf(entry: unknown): string | undefined {
  if (typeof entry === 'string') return entry
  const t = entry !== null && typeof entry === 'object' ? (entry as Record<string, unknown>).text : undefined
  return typeof t === 'string' ? t : undefined
}

/**
 * Checks the debrief JSON against its window. With no window (events mode) nothing is stripped
 * or flagged. An entry with `at` outside the window is removed; one with no `at` is kept and
 * counted; a corrections or tool_denials list that reports a kind the window's breadcrumbs lack is flagged.
 */
export function checkDebrief(text: string, window: DebriefWindow | undefined, users: readonly UserMessage[] = []): DebriefCheck {
  let j: unknown
  try {
    j = JSON.parse(text)
  } catch {
    j = undefined
  }
  if (j === null || typeof j !== 'object' || Array.isArray(j)) return { parsed: false, evidenced: 0, untimed: 0, debrief: {}, stripped: [], strippedCount: 0, flagged: [], noAt: 0, clean: true, lines: [] }
  const debrief: Record<string, unknown> = { ...(j as Record<string, unknown>) }
  if (!window) return { parsed: true, evidenced: 0, untimed: 0, debrief, stripped: [], strippedCount: 0, flagged: [], noAt: 0, clean: true, lines: ['debrief check: clean (no breadcrumb window to check against)'] }
  const firstMs = Date.parse(window.firstTs)
  const lastMs = Date.parse(window.lastTs)
  const stripped: string[] = []
  const flagged: string[] = []
  let strippedCount = 0
  let noAt = 0
  let evidenced = 0
  let untimed = 0
  let flaggedByEvidence = false
  for (const key of AT_LISTS) {
    const list = debrief[key]
    if (!Array.isArray(list)) continue
    const kept: unknown[] = []
    let proven = 0
    const why: string[] = []
    for (const entry of list) {
      const at = atOf(entry)
      if (at === undefined) {
        noAt += 1
        kept.push(entry)
        continue
      }
      if ('line' in at) {
        if (at.line > window.watermark && at.line <= window.end) kept.push(entry)
        else why.push(`line ${at.line} is ${at.line <= window.watermark ? 'before' : 'after'} lines ${window.firstLine}-${window.lastLine}`)
      } else if (Number.isNaN(firstMs) || Number.isNaN(lastMs) || (at.ms >= firstMs && at.ms <= lastMs)) {
        // MOD-38: a correction whose quote the transcript holds at its time is evidence whatever the breadcrumbs say
        const quote = key === 'corrections' ? quoteOf(entry) : undefined
        const how = quote === undefined ? undefined : quoteEvidenced(quote, at.ms, users)
        if (how !== undefined) {
          proven += 1
          if (how === 'transcript-untimed') untimed += 1
          kept.push({ ...(entry as Record<string, unknown>), source: how })
        } else kept.push(entry)
      } else why.push(`${new Date(at.ms).toISOString()} is ${at.ms < firstMs ? 'before' : 'after'} ${window.firstTs} to ${window.lastTs}`)
    }
    if (proven > 0) debrief[key] = kept
    if (why.length > 0) {
      strippedCount += why.length
      stripped.push(`stripped ${why.length} ${key} ${why.length === 1 ? 'entry' : 'entries'} outside the window: ${why.slice(0, 3).join('; ')}${why.length > 3 ? '; ...' : ''}`)
      debrief[key] = kept
    }
    const needs = KIND_NEEDS[key]
    evidenced += proven
    if (needs && proven > 0 && !needs.some(k => window.kinds.includes(k))) flaggedByEvidence = true
    if (needs && kept.length - proven > 0 && !needs.some(k => window.kinds.includes(k))) {
      flagged.push(`flagged ${key}: it reports ${kept.length - proven} but lines ${window.firstLine}-${window.lastLine} hold no ${needs.join(' or ')} breadcrumb`)
    }
  }
  const clean = strippedCount === 0 && flagged.length === 0
  const lines = [...stripped, ...flagged]
  if (noAt > 0) lines.push(`kept ${noAt} ${noAt === 1 ? 'entry' : 'entries'} with no usable at`)
  const onlyEvidence = clean && evidenced > 0 && flaggedByEvidence
  lines.unshift(onlyEvidence ? `debrief check: clean (${evidenced} ${evidenced === 1 ? 'correction' : 'corrections'} evidenced by the transcript${untimed > 0 ? `, ${untimed} untimed: the transcript file could not be read, so the quote alone was matched` : ''}, none in the breadcrumbs)` : clean ? 'debrief check: clean' : `debrief check: ${strippedCount} stripped, ${flagged.length} flagged`)
  return { parsed: true, evidenced, untimed, debrief, stripped, strippedCount, flagged, noAt, clean, lines }
}

const HOST_TEXT = /permission classifier|\bclassifier\b|safety check|\bengine\b|\bhost'?s?\b|\b(?:your|the user'?s|the person'?s|user|their|own) hooks?\b/i

const surfaceWords = (s: string): string[] => s.toLowerCase().match(/[a-z]+/g) ?? []

/** The surface names a mod surface (the command, hook or file, in any wording that contains the enum word). */
export const isModSurface = (surface: string): boolean => surfaceWords(surface).some(w => (MOD_SURFACES as readonly string[]).includes(w))

type Loose = { surface?: unknown; title?: unknown; body?: unknown }
const str = (v: unknown): string => (typeof v === 'string' ? v : '')

/** A finding is about the host when its surface is not a mod surface or its text names the classifier, a safety check, the engine or the person's own hooks. */
export const isHostFinding = (f: Loose): boolean => !isModSurface(str(f.surface)) || HOST_TEXT.test(`${str(f.surface)}\n${str(f.title)}\n${str(f.body)}`)

/** The findings split: about the mod, and about the host (never posted). */
export function splitFindings<T extends Loose>(findings: readonly T[]): { mod: T[]; host: T[] } {
  const mod: T[] = []
  const host: T[] = []
  for (const f of findings) (isHostFinding(f) ? host : mod).push(f)
  return { mod, host }
}

