// Session health across compaction (SPEC part 2E): the delegation state as
// lines, the instructions a compaction is given, and the system prompt's
// "Delegation state" section. Pure: no `$`.

import { askPosture } from './findings'
import { VERDICT_POSTURE } from './verdicttool'

export type StateSnapshot = {
  /** Briefed workers `$.agent.list()` says are running. */
  running: { task: string; tier: string; agentId: string; at?: number }[]
  /** Workers that handed back and whose verdict is not in yet. */
  pending: { task: string; agentId?: string }[]
  /** This session's verdict lines, oldest first. */
  recent: { line: string; at: number }[]
  /**
   * The scheduler queue, head first. MOD-12: `ready` is the advice line for a
   * row a free slot waits for (the brain makes its spawn); it replaces the row's
   * queued line. MOD-23: `waits` says what a row waits for when it is a resource
   * (`waiting for resource blender-live (held by T-1)`); it is no call for the brain.
   */
  queued: { task: string; position: number; ready?: string; waits?: string }[]
  /** Advice the brain (or Ben) has not acted on: `<task>: <next>`. */
  owed: string[]
  /** MOD-4: owed tasks checked and older than 24 hours: counted on one line, not printed. */
  owedOlder?: string[]
  debrief?: { at: number; agentId?: string; path?: string; finishedAt?: number }
  eval?: { tier: string; sha: string; pass?: number; total?: number; at: number; running?: boolean; agentId?: string }
  /** PRs the workers' reports named. */
  prs: string[]
  /** MOD-31: a debrief's post-findings question is waiting for the person's answer. */
  postAsk?: { count: number; repo: string }
  /** MOD-33: proposals of the latest debrief with no done or dismissed record. */
  proposalsOpen?: number
}

/** One `delegation.recent.<session>` row: a verdict as the one line has it, and what it leaves owed. */
export type RecentVerdict = { task: string; attempt: number; verdict: string; line: string; at: number; owed?: string; pr?: string }

/**
 * What is owed: each task's latest verdict that left advice undone, unless the
 * task is running, pending or queued again, or (MOD-4) retired: its work is on
 * the default branch, or the brain accepted it by hand.
 */
export function owedRowsFrom(recent: readonly RecentVerdict[], busy: ReadonlySet<string>, retired: ReadonlySet<string> = new Set()): RecentVerdict[] {
  const latest = new Map<string, RecentVerdict>()
  for (const r of recent) latest.set(r.task, r)
  return [...latest.values()].filter(r => r.owed !== undefined && !busy.has(r.task) && !retired.has(r.task))
}

export function owedFrom(recent: readonly RecentVerdict[], busy: ReadonlySet<string>, retired: ReadonlySet<string> = new Set()): string[] {
  return owedRowsFrom(recent, busy, retired).map(r => r.owed as string)
}

/** MOD-4: an owed row's age past which, once it has been checked, it is only counted. */
export const OWED_LIVE_MS = 24 * 60 * 60 * 1000

/** MOD-4: owed rows not yet checked or younger than 24 hours print in full (`live`); the rest are named by task (`older`). */
export function splitOwed(rows: readonly { task: string; text: string; at: number; checked?: boolean }[], now: number): { live: string[]; older: string[] } {
  const live: string[] = []
  const older: string[] = []
  for (const r of rows) {
    if (r.checked && now - r.at >= OWED_LIVE_MS) older.push(r.task)
    else live.push(r.text)
  }
  return { live, older }
}

/** The PRs the reports named (`pr=` other than none), each once. */
export const prsFrom = (recent: readonly RecentVerdict[]): string[] =>
  [...new Set(recent.map(r => r.pr ?? '').filter(pr => pr !== '' && pr !== 'none'))]

/**
 * MOD-15: the posture line the state section carries while the brain has a
 * call of its own to make: a `ready:` row's spawn call, or a respawn block's
 * Agent call. MOD-23: or a review block's (MOD-21: the reviewer's Agent call).
 * The person is asked about the three things the brain cannot decide alone.
 */
export const ACT_POSTURE =
  'Posture: make a ready: row’s spawn call, a respawn block’s Agent call or a pending review block’s Agent call without asking the person; ask only when a verdict is refuted on a claim you cannot amend, a worker is over-spend, or an amend needs the person’s approval.'

/** MOD-15: an owed row whose advice is a respawn: its spawn block is the brain's to make. */
export const isRespawnOwed = (owed: string): boolean => /^[^\s:]+: respawn at \S+ — /.test(owed)

/** MOD-23: an owed row whose advice is a review (MOD-21): its reviewer spawn block is the brain's to make. */
export const isReviewOwed = (owed: string): boolean => /^[^\s:]+: review$/.test(owed)

/** MOD-15: is a row ready (a free slot waits for it), a respawn block pending, or (MOD-23) a review spawn block? */
export const actPending = (s: Pick<StateSnapshot, 'queued' | 'owed'>): boolean => s.queued.some(q => q.ready !== undefined) || s.owed.some(o => isRespawnOwed(o) || isReviewOwed(o))

export const emptySnapshot = (): StateSnapshot => ({ running: [], pending: [], recent: [], queued: [], owed: [], prs: [] })

export const isEmptyState = (s: StateSnapshot): boolean => s.running.length === 0 && s.pending.length === 0 && s.queued.length === 0 && s.owed.length === 0 && (s.owedOlder ?? []).length === 0

export const SECTION_ID = 'chassis-delegation:state'
export const HEADER = 'Delegation state (chassis-delegation):'
export const MAX_LINES = 40
const RECENT = 5

export const KEEP_VERBATIM =
  'KEEP VERBATIM: (1) the delegation state below; (2) the release recipe pointer (session scratchpad FOLDnn scripts); (3) the brief and report contracts `[[brief v=1 …]]` / `[[report v=1 …]]`; (4) every card held for Ben and every item owed by Ben.'

/** `2026-10-03 14:00Z` */
export const stamp = (ms: number): string => `${new Date(ms).toISOString().slice(0, 16).replace('T', ' ')}Z`

/**
 * The state, one line per fact, `HEADER` first, at most 40 lines: running
 * workers, pending verdicts, queued spawns and what is owed come first (they
 * are what the brain acts on), then the last 5 verdicts, then the last debrief
 * and eval and the PRs reports named.
 */
export function renderState(s: StateSnapshot, reserve = 0): string[] {
  const live = [
    ...s.running.map(r => `- running: ${r.task} ${r.tier} agent ${r.agentId}${r.at !== undefined ? ` since ${stamp(r.at)}` : ''}`),
    ...s.pending.map(p => `- pending verdict: ${p.task}${p.agentId ? ` agent ${p.agentId}` : ''}`),
    ...s.queued.map(q => (q.ready ? `- ${q.ready}` : `- queued: ${q.task} (position ${q.position})${q.waits ? ` — ${q.waits}` : ''}`)),
    ...s.owed.map(o => `- owed: ${o}`),
  ]
  const older = s.owedOlder ?? []
  // the count line is the last live line and is never cut for room
  const tail = [...(older.length > 0 ? [`- ${older.length} older owed rows: ${older.join(', ')}`] : []), ...((s.proposalsOpen ?? 0) > 0 ? [`- ${s.proposalsOpen} debrief proposals open \u2014 /delegation debrief apply`] : [])]
  const history = [
    ...s.recent.slice(-RECENT).map(r => `- verdict: ${r.line}`),
    ...(s.debrief
      ? [`- last debrief: ${stamp(s.debrief.at)}${s.debrief.agentId ? ` agent ${s.debrief.agentId}` : ''} — ${s.debrief.path ?? (s.debrief.finishedAt ? 'finished' : 'running')}`]
      : []),
    ...(s.eval
      ? [
          s.eval.running
            ? `- eval running: ${s.eval.tier} at ${s.eval.sha.slice(0, 8)}${s.eval.agentId ? ` agent ${s.eval.agentId}` : ''}`
            : `- last eval: ${s.eval.tier} ${s.eval.pass ?? '?'}/${s.eval.total ?? '?'} at ${s.eval.sha.slice(0, 8)} (${stamp(s.eval.at)})`,
        ]
      : []),
    ...(s.prs.length > 0 ? [`- PRs named in reports: ${s.prs.join(', ')}`] : []),
  ]
  const room = MAX_LINES - 1 - reserve - tail.length
  // History keeps at least its verdicts when live lines would crowd it out.
  const keepHistory = Math.min(history.length, Math.max(RECENT, room - live.length))
  const keepLive = Math.min(live.length, room - keepHistory)
  const liveShown = live.length > keepLive ? [...live.slice(0, keepLive - 1), `- … ${live.length - keepLive + 1} more`] : live
  return [HEADER, ...liveShown, ...tail, ...history.slice(0, keepHistory)]
}

export const appendInstructions = (existing: string | undefined, block: string): string => (existing ?? '') + '\n' + block

/** What a compaction is told to keep: KEEP VERBATIM, the release recipe pointer, the state. */
export function compactBlock(s: StateSnapshot, scratchpad?: string): string {
  const recipe = scratchpad ? [`Release recipe: the FOLDnn scripts in ${scratchpad}`] : []
  const state = isEmptyState(s) && (s.proposalsOpen ?? 0) === 0 && s.recent.length === 0 && !s.debrief && !s.eval ? [`${HEADER} nothing running, nothing owed.`] : renderState(s)
  return [KEEP_VERBATIM, ...recipe, ...state].join('\n')
}

/**
 * The system prompt's section: present while something runs, waits or is owed,
 * and, with `posture` (GH-113: a premium brain under delegateOnly), always, with
 * the posture lines right under the header; the 40-line cap holds either way.
 * MOD-15: while a row is ready or a respawn block is pending, one more posture
 * line (ACT_POSTURE) says to make the call without asking. MOD-64: `verdictTool` (wakes off) adds the
 * verdict-tool posture line while a worker runs or awaits its verdict.
 */
export function composeSection(s: StateSnapshot, posture: readonly string[] = [], verdictTool = false): { id: string; text: string; scope: 'session' } | undefined {
  // MOD-15: one more posture line while a row is ready or a respawn block is pending
  const acting0 = actPending(s) ? [...posture, ACT_POSTURE] : posture
  // MOD-64: wakes off and a worker running or awaiting its verdict: the brain waits for the verdict itself, in the hand-back turn
  const acting = verdictTool && (s.running.length > 0 || s.pending.length > 0) ? [...acting0, VERDICT_POSTURE] : acting0
  // MOD-31: while a post-findings question waits, one more posture line
  const lines = s.postAsk ? [...acting, askPosture(s.postAsk.count, s.postAsk.repo)] : acting
  const quiet = isEmptyState(s) && (s.proposalsOpen ?? 0) === 0
  if (quiet && lines.length === 0) return undefined
  const body = quiet && s.recent.length === 0 ? [HEADER, '- nothing running, nothing owed.'] : renderState(s, lines.length)
  const [head, ...rest] = body as [string, ...string[]]
  return { id: SECTION_ID, text: [head, ...lines, ...rest].join('\n'), scope: 'session' }
}

