// GH-111: the `card` tool. The person says a task in a sentence; the brain looks
// at the repo, chooses the scope globs and calls this with the fields. Pure: it
// validates them, assigns the next free id in the card folder and renders the
// card the README documents. register.ts writes it and runs the dry run (or the
// dispatch) through the same code `/dispatch <ID>` runs.
// MOD-23: `resources` names what the worker holds while it runs, and `lanes` splits one
// sentence into several cards (one per worker) with sequential ids, the shared fields
// and each lane's own scope.
import { RESOURCE_NAME, scopeOverlap } from './brief'
import { dollars, spendCeiling } from './cost'
import { scopeLooksProse, yamlScalar } from './dispatch'
import { gateCommandTemplates } from './gates'
import { matchGlob } from './norepo'
import { tierOf, type Tier } from './tier'
import { globMatches } from './verify-native'

/** What the validation needs from the effective config and the card folder. */
export type CardCtx = {
  domains: readonly string[]
  /** The ids in the effective gateMap. */
  gateIds: readonly string[]
  /** The file names in the card folder. */
  names: readonly string[]
  spendByTier: Readonly<Record<string, number>>
  /** repo=here: the repo has no origin/main, so the worker shares the checkout (the card says `repo: here`). */
  here?: boolean
  /** MOD-44: the checked absolute path of the other local repo this card is for; `domains`, `gateIds` and `spendByTier` are then that repo's. */
  repoPath?: string
}

/** MOD-22: where the worker runs: in its own worktree (the default), in the session's checkout, or with no repo at all. */
export type CardRepo = 'worktree' | 'here' | 'none'
export const CARD_REPOS: readonly CardRepo[] = ['worktree', 'here', 'none']

export type NewCard = {
  id: string
  /** The file name inside the card folder. */
  file: string
  text: string
  title: string
  domain: string
  tier: Tier
  scope: string[]
  forbid: string[]
  gate: string[]
  redTest: string
  budget: number
  spend: number
  /** MOD-22: the mode the card was written for; MOD-44: or the absolute path of another local repo. */
  repo: CardRepo | string
  /** MOD-23: the exclusive resources the card holds while it runs. */
  resources: string[]
}

export const CARD_TOOL = {
  name: 'card',
  description:
    'When the person describes work to delegate, look at the repo to choose scope globs, then call this with the task (research or extraction with outputs outside the repo: repo none or here, scope = the output folder). For several workers at once pass lanes: one { title, scope } per worker, each with its own output folder, and put what the lanes share but none may touch (a notes file) in forbid; name a live app only one worker may use in resources, and the queue runs the lanes that hold it one at a time. It writes the card (one per lane), runs the dry run and returns the brief; show the person the summary and dispatch when they say go (call dispatch, or call this with dispatch: true when they already said to go ahead). Never ask the person to edit a card file.',
  inputSchema: {
    type: 'object',
    properties: {
      title: { type: 'string', description: 'One line that says what done looks like' },
      why: { type: 'string', description: 'Two or three sentences: why this task' },
      doneWhen: { type: 'array', items: { type: 'string' }, description: 'Checkable statements: what is true when it is done' },
      scope: { type: 'array', items: { type: 'string' }, description: 'Globs or paths the worker may change, e.g. ["src/feature/**", "tests/test_feature.py"]; an absolute path or glob (a leading ~ is the home folder) names a folder outside the repo, and the first one is the output folder. Not prose. In a repo path * crosses folders (artifacts/*.html also matches artifacts/kit/index.html), and no repo glob stays in one folder, so list the files. Required unless lanes carry their own; given with lanes, it is refused' },
      forbid: { type: 'array', items: { type: 'string' }, description: 'Globs the worker must not touch (default none); absolute paths and globs too. In a repo path * crosses folders (artifacts/*.html also matches artifacts/kit/index.html), and no repo glob stays in one folder, so list the files' },
      repo: { type: 'string', description: "worktree (default): the worker gets its own worktree; here: it works in this checkout; none: no repo at all. For research or extraction with outputs outside the repo use none or here, with scope = the output folder. An absolute path (the folder holding .git of another local repo, ~ allowed) delegates into that repo: the card goes in its card folder (or, with no .chassis-delegation.json there, under this session's .delegation/cards/<its folder name>/), the worktree is cut from its origin/main beside it, and the gate map, domains and spend are its own (with no config, its detected test command; gate may then be a one-off command such as \"npm run build\")" },
      redTest: { type: 'string', description: 'The command or test that fails now and passes after, or "none" for docs-only work' },
      tier: { type: 'string', description: 'economy, standard (default), frontier or premium' },
      domain: { type: 'string', description: 'One of the repo domains (default: ops when the repo has it, else the first)' },
      gate: { type: 'string', description: 'Gate id(s) from gateMap, comma-separated (default: the first); for a repo given as a path also one command (words only, no comma), e.g. "npm run build"' },
      budget: { type: 'number', description: 'Attempts before the task is handed back (default 2)' },
      spend: { type: 'number', description: "Dollars one attempt may spend; 0 = no ceiling (default: the tier's)" },
      resources: { type: 'array', items: { type: 'string' }, description: 'Exclusive resources the worker holds while it runs, e.g. ["blender-live"] (one live app with one open file): one plain word each. A card that names a resource a running worker holds waits in the queue until that worker hands back' },
      lanes: {
        type: 'array',
        description: 'Fan-out: one card per lane, with sequential ids, the shared why, gate, tier, repo, resources and forbid, and each lane its own scope (and so its own output folder). Lanes whose scopes overlap are refused. Give the shared title/doneWhen as the umbrella; a lane without its own doneWhen takes the shared one',
        items: {
          type: 'object',
          properties: {
            title: { type: 'string', description: 'One line that says what this lane delivers' },
            scope: { type: 'array', items: { type: 'string' }, description: "The lane's own globs or paths, its output folder first; disjoint from every other lane's" },
            doneWhen: { type: 'array', items: { type: 'string' }, description: 'Checkable statements for this lane (default: the shared doneWhen)' },
          },
          required: ['title', 'scope'],
          additionalProperties: false,
        },
      },
      dispatch: { type: 'boolean', description: 'Dispatch right after writing the card, instead of the dry run (default false)' },
    },
    required: ['title', 'why', 'doneWhen', 'redTest'],
    additionalProperties: false,
  },
} as const

export const CARD_TOOL_NAME = 'mcp__chassis-delegation__card'

const GLOB_EXAMPLE = 'game_decompiler/**, tests/test_rom.py'
const text = (v: unknown): string => (typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : '')

/** The id prefix of a domain: frontend FE, backend BE, ops OPS, else its first three letters upper-cased. */
export function domainPrefix(domain: string): string {
  if (domain === 'frontend') return 'FE'
  if (domain === 'backend') return 'BE'
  if (domain === 'ops') return 'OPS'
  return domain.slice(0, 3).toUpperCase().replace(/[^A-Z0-9]/g, '') || 'OPS'
}

/** The next free number among `names` for `prefix` (OPS-1-a.md, OPS-3b-c.md → 4). */
export function nextNumber(names: readonly string[], prefix: string): number {
  let max = 0
  for (const n of names) {
    const m = new RegExp(`^${prefix}-(\\d+)`).exec(n)
    if (m) max = Math.max(max, Number(m[1]))
  }
  return max + 1
}

/** The title as a file-name slug: lower case, at most six words joined by `-`. */
export const slugOf = (title: string): string => (title.toLowerCase().match(/[a-z0-9]+/g) ?? []).slice(0, 6).join('-') || 'task'

function globs(key: 'scope' | 'forbid', v: unknown, required: boolean): string[] | { error: string } {
  if (v === undefined && !required) return []
  if (!Array.isArray(v) || v.some(x => typeof x !== 'string')) return { error: `${key} must be a list of globs, e.g. ${GLOB_EXAMPLE}` }
  const list = (v as string[]).map(s => s.trim()).filter(Boolean)
  if (required && list.length === 0) return { error: `scope needs at least one glob, e.g. ${GLOB_EXAMPLE}` }
  const prose = list.find(s => scopeLooksProse([s]))
  if (prose !== undefined) return { error: `${key} must be globs, e.g. ${GLOB_EXAMPLE} (got "${prose}")` }
  const bad = list.find(s => /[,"'\]\\]/.test(s))
  if (bad !== undefined) return { error: `${key} entry "${bad}" cannot hold a comma, quote, backslash or ]]; list one glob per entry` }
  return list
}

/** MOD-23: the card's `resources`: a list of plain words, each once; none when absent. */
function resourceNames(v: unknown): string[] | { error: string } {
  if (v === undefined) return []
  if (!Array.isArray(v) || v.some(x => typeof x !== 'string')) return { error: 'resources must be a list of names, e.g. ["blender-live"]' }
  const out: string[] = []
  for (const raw of v as string[]) {
    const name = raw.trim()
    if (!RESOURCE_NAME.test(name)) return { error: `resources entry "${raw}" must be one plain word (letters, digits, . _ : -), e.g. blender-live` }
    if (!out.includes(name)) out.push(name)
  }
  return out
}

/**
 * Validate the tool input and render the card, or say exactly what to change. Writes nothing.
 * `at` (MOD-23, a lane's place) is added to the next free number, so lane 2 takes id N+1.
 */
export function cardFromFields(input: Record<string, unknown>, ctx: CardCtx, at = 0): NewCard | { error: string } {
  const title = text(input.title)
  if (title === '') return { error: 'title is required: one line that says what done looks like' }
  const why = typeof input.why === 'string' ? input.why.trim() : ''
  if (why === '') return { error: 'why is required: two or three sentences' }
  const done = Array.isArray(input.doneWhen) ? (input.doneWhen as unknown[]).map(text).filter(Boolean) : []
  if (done.length === 0) return { error: 'doneWhen is required: a list of checkable statements' }

  const scope = globs('scope', input.scope, true)
  if ('error' in scope) return scope
  const forbid = globs('forbid', input.forbid, false)
  if ('error' in forbid) return forbid
  const resources = resourceNames(input.resources)
  if ('error' in resources) return resources

  // MOD-22: no repo given keeps the old rule (a repo with no origin/main works in the checkout)
  // MOD-44: a path was resolved by the caller (ctx.repoPath); one that was not is refused here
  const repoIn = input.repo === undefined ? undefined : typeof input.repo === 'string' ? text(input.repo) : String(input.repo)
  if (repoIn !== undefined && ctx.repoPath === undefined && !(CARD_REPOS as readonly string[]).includes(repoIn)) {
    return { error: `repo must be worktree, here, none or the absolute path of a git checkout (got "${repoIn}")` }
  }
  const repo: CardRepo | string = ctx.repoPath ?? (repoIn as CardRepo | undefined) ?? (ctx.here ? 'here' : 'worktree')

  const redTest = text(input.redTest)
  if (redTest === '') return { error: 'redTest is required: the command or test that fails now and passes after, or "none" for docs-only work' }

  const tierIn = input.tier === undefined ? 'standard' : text(input.tier)
  const tier = tierOf(tierIn)
  if (tier === undefined) return { error: `tier ${tierIn} is not economy, standard, frontier or premium` }

  const domain = input.domain === undefined ? (ctx.domains.includes('ops') ? 'ops' : (ctx.domains[0] ?? 'ops')) : text(input.domain)
  if (!ctx.domains.includes(domain)) return { error: `domain ${domain} is not one of ${ctx.domains.join(', ')}` }

  // MOD-44: for another repo, one command (words, no comma) is a gate of its own, as the person would type it
  const oneOff = ctx.repoPath !== undefined && typeof input.gate === 'string' && text(input.gate) !== '' && !/^[A-Za-z0-9_.-]+(\s*,\s*[A-Za-z0-9_.-]+)*$/.test(text(input.gate))
  if (ctx.gateIds.length === 0 && !oneOff) {
    return { error: ctx.repoPath !== undefined ? `${ctx.repoPath} has no gate: no gateMap in its .chassis-delegation.json and no test command found (package.json scripts.test, pytest, cargo or go); name one in gate, e.g. "npm run build"` : 'gateMap has no gate; run /delegation setup, or add a gateMap entry in .chassis-delegation.json' }
  }
  let gate: string[]
  if (oneOff) {
    const cmd = text(input.gate)
    if (cmd.includes(',')) return { error: 'a one-off gate command cannot hold a comma; name one command, or gate ids from gateMap' }
    const t = gateCommandTemplates(cmd)
    if ('reason' in t) return { error: `gate command refused: ${t.reason}` }
    gate = [cmd]
  } else {
    gate = input.gate === undefined ? [ctx.gateIds[0] as string] : text(input.gate).split(/\s*,\s*/).filter(Boolean)
    if (gate.length === 0) return { error: `gate is empty; the ids are ${ctx.gateIds.join(', ')}` }
    for (const g of gate) if (!ctx.gateIds.includes(g)) return { error: `gate ${g} is not in gateMap; the ids are ${ctx.gateIds.join(', ')}` }
  }

  const budget = input.budget === undefined ? 2 : Number(input.budget)
  if (!Number.isInteger(budget) || budget < 1) return { error: 'budget must be a whole number of attempts, 1 or more' }
  const spendIn = input.spend === undefined ? undefined : Number(input.spend)
  if (spendIn !== undefined && (!Number.isFinite(spendIn) || spendIn < 0)) return { error: 'spend must be dollars, 0 or more (0 = no ceiling)' }
  const spend = spendIn ?? spendCeiling(undefined, tier, ctx.spendByTier)

  const prefix = domainPrefix(domain)
  const id = `${prefix}-${nextNumber(ctx.names, prefix) + at}`
  const body = `---
id: ${id}
title: ${yamlScalar(title)}
domain: ${domain}
tier: ${tier}
status: queued
${repo === 'worktree' ? '' : `repo: ${repo}\n`}scope: [${scope.join(', ')}]
forbid: [${forbid.join(', ')}]
${resources.length > 0 ? `resources: [${resources.join(', ')}]\n` : ''}red_test: ${yamlScalar(redTest)}
gate: ${gate.join(', ')}
budget: ${budget}-attempts
spend: ${spend}
---
## Why

${why}

## Done when

${done.map(d => `- ${d}`).join('\n')}
`
  return { id, file: `${id}-${slugOf(title)}.md`, text: body, title, domain, tier, scope, forbid, gate, redTest, budget, spend, repo, resources }
}

/**
 * MOD-23: the cards one call writes. Without `lanes`, the one card `cardFromFields` renders. With them, one card per
 * lane, in order, ids N, N+1, … : the shared why, gate, tier, repo, resources, budget and forbid, and each lane its own
 * title, scope and (when it has one) doneWhen. A shared scope beside lanes is refused, and so are lanes whose scopes
 * overlap, naming both: two workers must not own the same files. Nothing is returned to write on a refusal.
 */
export function cardsFromFields(input: Record<string, unknown>, ctx: CardCtx): NewCard[] | { error: string } {
  if (input.lanes === undefined) {
    const one = cardFromFields(input, ctx)
    return 'error' in one ? one : [one]
  }
  const raw = input.lanes
  if (!Array.isArray(raw) || raw.length === 0) return { error: 'lanes must be a list of { title, scope, doneWhen? }, one per worker' }
  if (input.scope !== undefined) return { error: 'scope belongs to each lane when lanes are given (lanes: [{ title, scope }]); drop the shared scope' }
  const lanes: { title: string; scope: string[]; doneWhen?: string[] }[] = []
  for (const [i, entry] of (raw as unknown[]).entries()) {
    const n = i + 1
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) return { error: `lane ${n} must be { title, scope, doneWhen? }` }
    const lane = entry as Record<string, unknown>
    const title = text(lane.title)
    if (title === '') return { error: `lane ${n} needs a title: one line that says what the lane delivers` }
    const scope = globs('scope', lane.scope, true)
    if ('error' in scope) return { error: `lane ${n} (${title}): ${scope.error}` }
    let doneWhen: string[] | undefined
    if (lane.doneWhen !== undefined) {
      doneWhen = Array.isArray(lane.doneWhen) ? (lane.doneWhen as unknown[]).map(text).filter(Boolean) : []
      if (doneWhen.length === 0) return { error: `lane ${n} (${title}): doneWhen must be a list of checkable statements` }
    }
    lanes.push({ title, scope, ...(doneWhen ? { doneWhen } : {}) })
  }
  for (let i = 0; i < lanes.length; i += 1) {
    for (let j = i + 1; j < lanes.length; j += 1) {
      const a = lanes[i] as (typeof lanes)[number]
      const b = lanes[j] as (typeof lanes)[number]
      const pair = scopeOverlap(a.scope, b.scope)
      if (pair) return { error: `lanes overlap: lane ${i + 1} "${a.title}" scope ${pair.mine} overlaps lane ${j + 1} "${b.title}" scope ${pair.theirs}; give each lane its own output folder` }
    }
  }
  const { lanes: _lanes, ...shared } = input
  const made: NewCard[] = []
  for (const [i, lane] of lanes.entries()) {
    const one = cardFromFields({ ...shared, title: lane.title, scope: lane.scope, ...(lane.doneWhen ? { doneWhen: lane.doneWhen } : {}) }, ctx, i)
    if ('error' in one) return one
    made.push(one)
  }
  return made
}

/** `OPS-1 · standard → sonnet · scope a, b · gate test · red: cmd · 2 attempts · $6 ceiling`; a card that is not a worktree card names its repo after the scope (`… · repo none · gate test …`). */
export const cardSummary = (c: Pick<NewCard, 'id' | 'tier' | 'scope' | 'gate' | 'redTest' | 'budget' | 'spend'> & { repo?: CardRepo | string; resources?: readonly string[] }, alias: string): string =>
  [c.id, `${c.tier} → ${alias}`, `scope ${c.scope.join(', ')}`, ...(c.repo && c.repo !== 'worktree' ? [`repo ${c.repo}`] : []), ...(c.resources && c.resources.length > 0 ? [`resources ${c.resources.join(', ')}`] : []), `gate ${c.gate.join(', ')}`, `red: ${c.redTest}`, `${c.budget} attempts`, c.spend > 0 ? `${dollars(c.spend)} ceiling` : 'no ceiling'].join(' · ')

/** The closing line of the dry-run answer; MOD-23: with lanes, every id. */
export const sayGo = (ids: string | readonly string[]): string => `Say go and Claude dispatches ${typeof ids === 'string' ? ids : ids.join(', ')}.`

// ---- MOD-29: the forbid collisions the dry run warns about -----------------------------
// A forbid glob that can match a path the card's scope or done-when names is refused by the
// verifier on that path, so the dry run says so before a worker spends an attempt on it. The
// rule is the verifier's own: a repo glob (globMatches) lets * cross folders, an absolute one
// (matchGlob) keeps * inside one folder. A literal path is matched by that matcher; a glob
// against a glob is an intersection test over the same token rules. Pure.

/** One token of a glob: a literal character, a run of characters (`*`), or one character passing a test (`?`, a class). */
type GlobTok = { kind: 'lit'; c: string } | { kind: 'star'; slash: boolean } | { kind: 'one'; test: (c: string) => boolean }

/** A leading `/` or `~` names a folder outside the repo: the absolute rule. */
const isAbsoluteGlob = (g: string): boolean => g.startsWith('/') || g.startsWith('~')

/** The glob characters the verifier reads for this rule (an absolute glob reads `{` and not `[`). */
const hasWild = (g: string, abs: boolean): boolean => (abs ? /[*?{]/ : /[*?[]/).test(g)

/** The verifier's repo rule as tokens: `*` crosses folders, `?` is one character, `[…]` a class, a trailing `/` means everything under it. */
function repoToks(glob: string): GlobTok[] {
  const g = glob.endsWith('/') ? `${glob}*` : glob
  const out: GlobTok[] = []
  for (let i = 0; i < g.length; i += 1) {
    const c = g[i] as string
    if (c === '*') out.push({ kind: 'star', slash: true })
    else if (c === '?') out.push({ kind: 'one', test: () => true })
    else if (c === '[' && g.indexOf(']', i + 2) >= 0) {
      const close = g.indexOf(']', i + 2)
      const body = g.slice(i + 1, close).replace(/^!/, '^')
      let re: RegExp | undefined
      try {
        re = new RegExp(`^[${body}]$`, 's')
      } catch {
        re = undefined
      }
      if (re) out.push({ kind: 'one', test: ch => (re as RegExp).test(ch) })
      else for (const ch of g.slice(i, close + 1)) out.push({ kind: 'lit', c: ch })
      i = close
    } else out.push({ kind: 'lit', c })
  }
  return out
}

/** The absolute rule (globToRegExp) as alternative token lists: `*` stays in one folder, `**` crosses, `?` is one non-`/` character, `{a,b}` either, and a double star then a slash zero or more folders. */
function absAlts(g: string, i: number): GlobTok[][] {
  if (i >= g.length) return [[]]
  const c = g[i] as string
  if (c === '*' && g[i + 1] === '*') {
    if (g[i + 2] === '/') {
      const tails = absAlts(g, i + 3)
      return [...tails, ...tails.map(t => [{ kind: 'star', slash: true } as GlobTok, { kind: 'lit', c: '/' } as GlobTok, ...t])]
    }
    return absAlts(g, i + 2).map(t => [{ kind: 'star', slash: true } as GlobTok, ...t])
  }
  if (c === '*') return absAlts(g, i + 1).map(t => [{ kind: 'star', slash: false } as GlobTok, ...t])
  if (c === '?') return absAlts(g, i + 1).map(t => [{ kind: 'one', test: ch => ch !== '/' } as GlobTok, ...t])
  if (c === '{') {
    const close = g.indexOf('}', i)
    if (close >= 0) {
      const tails = absAlts(g, close + 1)
      return g.slice(i + 1, close).split(',').flatMap(alt => tails.map(t => [...alt.split('').map(ch => ({ kind: 'lit', c: ch }) as GlobTok), ...t]))
    }
  }
  return absAlts(g, i + 1).map(t => [{ kind: 'lit', c } as GlobTok, ...t])
}

const globAlts = (glob: string, abs: boolean): GlobTok[][] => (abs ? absAlts(glob, 0) : [repoToks(glob)])

/** Whether one character can be both tokens' character (a class against a class or a wildcard is taken as possible). */
const accepts = (t: GlobTok, c: string): boolean => (t.kind === 'lit' ? t.c === c : t.kind === 'one' ? t.test(c) : t.slash || c !== '/')
const meets = (x: GlobTok, y: GlobTok): boolean => (x.kind === 'lit' ? accepts(y, x.c) : y.kind === 'lit' ? accepts(x, y.c) : true)

/** Whether some path matches both token lists: a product walk over the two patterns, a star skipping or taking a character. */
function globsCollide(a: readonly GlobTok[], b: readonly GlobTok[]): boolean {
  const width = b.length + 1
  const seen = new Set<number>()
  const todo: [number, number][] = [[0, 0]]
  while (todo.length > 0) {
    const [i, j] = todo.pop() as [number, number]
    if (seen.has(i * width + j)) continue
    seen.add(i * width + j)
    if (i === a.length && j === b.length) return true
    const x = a[i]
    const y = b[j]
    if (x?.kind === 'star') todo.push([i + 1, j])
    if (y?.kind === 'star') todo.push([i, j + 1])
    if (x === undefined || y === undefined || (x.kind === 'star' && y.kind === 'star')) continue
    if (!meets(x, y)) continue
    if (x.kind === 'star') todo.push([i, j + 1])
    else if (y.kind === 'star') todo.push([i + 1, j])
    else todo.push([i + 1, j + 1])
  }
  return false
}

/** Whether a scope entry, a done-when path or a forbid glob can name the same path (the verifier's rule for each). */
function collides(entry: string, forbid: string): boolean {
  const abs = isAbsoluteGlob(forbid)
  if (isAbsoluteGlob(entry) !== abs) return false
  // a literal entry is matched exactly as the verifier matches it
  if (!hasWild(entry, abs)) return abs ? matchGlob(entry, forbid) : globMatches(entry, forbid)
  const mine = globAlts(entry, abs)
  const theirs = globAlts(forbid, abs)
  return mine.some(x => theirs.some(y => globsCollide(x, y)))
}

/**
 * MOD-52: a word with its trailing punctuation and leading quotes off, and its emphasis off only in pairs: a run of `*` or `_`
 * at the start and the same run at the end (`**x**`, `*x*`, `__x__`) goes together. `**a/b.md:**` and `**a/b.md**:` both give
 * `a/b.md`; a glob word with a star inside (a double star then a folder, a star before a dot) comes through unchanged.
 */
const cleanWord = (w: string): string => {
  let s = w
  for (;;) {
    s = s.replace(/^["'(]+/, '').replace(/["'),;:!?.]+$/, '')
    const lead = /^[*_]+/.exec(s)?.[0] ?? ''
    const trail = /[*_]+$/.exec(s)?.[0] ?? ''
    if (lead === '' || lead !== trail || s.length <= 2 * lead.length) return s
    s = s.slice(lead.length, s.length - trail.length)
  }
}

/** MOD-52: whether a scope entry names this path: equal to it, or a glob that matches it under the rule of its own kind (repo or absolute). */
function namedBy(path: string, entry: string): boolean {
  if (entry === path) return true
  if (isAbsoluteGlob(entry) !== isAbsoluteGlob(path)) return false
  return isAbsoluteGlob(entry) ? matchGlob(path, entry) : globMatches(path, entry)
}

/** The path-like words of one done-when statement: a word with a slash and a dot, in backticks or bare, cleaned (MOD-52). */
export function donePaths(statement: string): string[] {
  const ticked = [...statement.matchAll(/`([^`]+)`/g)].map(m => cleanWord(m[1] as string))
  const bare = statement.replace(/`[^`]*`/g, ' ').split(/\s+/).map(cleanWord)
  return [...ticked, ...bare].filter(w => w.includes('/') && w.includes('.') && !/\s/.test(w))
}

/** The lines of a card body's `## Done when` section, up to the next `## ` heading (the Why is not read). */
export function doneWhenOf(body: string): string[] {
  const out: string[] = []
  let on = false
  for (const line of body.split('\n')) {
    if (/^##\s/.test(line)) {
      on = /^##\s+Done when\s*$/i.test(line.trim())
      continue
    }
    if (on) out.push(line)
  }
  return out
}

/** MOD-54: how many statements a Done when section holds: its list items, or its non-blank lines when it has no list. */
export function doneStatementCount(lines: readonly string[]): number {
  const items = lines.filter(l => /^\s*(?:[-*+]|\d+[.)])\s+\S/.test(l)).length
  return items > 0 ? items : lines.filter(l => l.trim() !== '').length
}

/**
 * The warnings for each forbid glob that collides with the card: `warning: forbid <glob> matches scope <entry>`
 * for a scope entry (literal or glob) the forbid can name, and `warning: forbid <glob> matches <path> named in
 * done-when` for a path-like word of a done-when statement. Nothing is refused; the card is still written.
 */
export function forbidCollisions(scope: readonly string[], forbid: readonly string[], doneWhen: readonly string[]): string[] {
  const out: string[] = []
  const paths = [...new Set(doneWhen.flatMap(donePaths))]
  for (const f of forbid) {
    if (f === '') continue
    for (const s of scope) {
      const line = s === '' ? undefined : `warning: forbid ${f} matches scope ${s}`
      if (line !== undefined && collides(s, f) && !out.includes(line)) out.push(line)
    }
    for (const p of paths) {
      // MOD-52: a path the scope already names is covered by the scope warning above
      if (scope.some(s => s !== '' && namedBy(p, s))) continue
      const line = `warning: forbid ${f} matches ${p} named in done-when`
      if (collides(p, f) && !out.includes(line)) out.push(line)
    }
  }
  return out
}


/**
 * MOD-55: the warnings for each path-like word of the red_test (the donePaths rule) the brief cannot let the worker
 * write: `warning: red_test names <path>, which is outside scope`, or `… which is inside forbid <glob>`. Nothing is
 * added to the scope; the card is still written.
 */
export function redTestWarnings(redTest: string, scope: readonly string[], forbid: readonly string[]): string[] {
  const out: string[] = []
  for (const p of new Set(donePaths(redTest))) {
    const f = forbid.find(g => g !== '' && collides(p, g))
    if (f !== undefined) out.push(`warning: red_test names ${p}, which is inside forbid ${f}`)
    else if (!scope.some(s => s !== '' && namedBy(p, s))) out.push(`warning: red_test names ${p}, which is outside scope`)
  }
  return out
}

files.hooks/lib/setup.ts:
// GH-109: `/delegation setup` and the `setup` tool. Phase 1 checks the repo and
// the tools the mod needs and names the exact fix for each failing check; the
// mod cannot run those fixes (its host-command allowlist has no git init, commit,
// remote or install). Phase 2, only when every required check holds, scaffolds
// the config from what was found and hands over by asking for the first task (GH-111). Pure: no `$`;
// register.ts gathers the probe with allowlisted reads and does the writes.
import { REPO_CONFIG_FILE } from './repoconfig'
import { PLUGIN_CARD_DIR } from './init'
import { DEFAULT_SPEND_BY_TIER } from './cost'

/** The tool names register.ts looks for on PATH. */
export const PATH_TOOLS = ['git', 'node', 'npm', 'pnpm', 'yarn', 'python3', 'pytest', 'cargo', 'go', 'gh'] as const
/** Files at the root whose presence the checks read. */
export const ROOT_MARKERS = ['package.json', 'pyproject.toml', 'pytest.ini', 'Cargo.toml', 'go.mod', 'package-lock.json', 'pnpm-lock.yaml', 'yarn.lock', 'requirements.txt', '.claude-plugin/plugin.json'] as const
/** The files and folders of the user's home that would shadow the mod's commands. */
export const SHADOWS = ['.claude/skills/delegation', '.claude/skills/dispatch', '.claude/commands/delegation.md', '.claude/commands/dispatch.md'] as const

export type SetupProbe = {
  root: string
  home: string
  inRepo: boolean
  toplevel?: string
  branch?: string
  hasCommit: boolean
  hasOriginMain: boolean
  dirty: boolean
  /** ROOT_MARKERS that exist. */
  markers: readonly string[]
  /** The text of package.json, when it exists and was readable. */
  packageJson?: string
  /** tests/ holds a test_*.py. */
  pyTests: boolean
  /** The PATH_TOOLS found in a PATH directory. */
  onPath: readonly string[]
  /** The SHADOWS (as `~`-relative paths) that exist. */
  shadows: readonly string[]
  /** Child folders of the root holding `.git`. */
  childRepos: readonly string[]
  /** The root's .gitignore text, if any. */
  gitignore?: string
  autoDebrief: boolean
}

export type SetupLine = { level: 'required' | 'advice'; ok: boolean; text: string; fix?: string }
export type Stack = 'node' | 'python' | 'rust' | 'go'
export type Gate = { command: string; stack: Stack; pm?: string; runner?: 'pytest' | 'unittest' }

const has = (p: SetupProbe, m: string): boolean => p.markers.includes(m)
const norm = (s: string): string => s.replace(/\/+$/, '')
const base = (s: string): string => norm(s).slice(norm(s).lastIndexOf('/') + 1) || 'project'

/** The package manager the lockfile names (npm without one). */
export const packageManager = (p: SetupProbe): string => (has(p, 'pnpm-lock.yaml') ? 'pnpm' : has(p, 'yarn.lock') ? 'yarn' : 'npm')

/** The test command the repo already has, or undefined. */
export function detectGate(p: SetupProbe): Gate | undefined {
  if (has(p, 'package.json') && p.packageJson !== undefined) {
    let test: unknown
    try {
      test = (JSON.parse(p.packageJson) as { scripts?: { test?: unknown } }).scripts?.test
    } catch {
      test = undefined
    }
    if (typeof test === 'string' && test.trim() !== '' && !/no test specified/i.test(test)) {
      const pm = packageManager(p)
      return { command: `${pm} test`, stack: 'node', pm }
    }
  }
  // python: pytest when the repo names it (pytest.ini) or it is installed; else the standard library's unittest, which needs nothing installed
  if (has(p, 'pyproject.toml') || has(p, 'pytest.ini') || p.pyTests) {
    if (has(p, 'pytest.ini') || p.onPath.includes('pytest')) return { command: 'pytest', stack: 'python', runner: 'pytest' }
    return { command: 'python3 -m unittest discover -s tests', stack: 'python', runner: 'unittest' }
  }
  if (has(p, 'Cargo.toml')) return { command: 'cargo test', stack: 'rust' }
  if (has(p, 'go.mod')) return { command: 'go test ./...', stack: 'go' }
  return undefined
}

const gateExample = (p: SetupProbe): string =>
  has(p, 'package.json')
    ? 'for example "scripts": {"test": "node --test"} in package.json'
    : has(p, 'Cargo.toml') || has(p, 'go.mod') || has(p, 'pyproject.toml')
      ? 'for example an empty test that passes'
      : 'for example a package.json with "scripts": {"test": "node --test"}, or a tests/test_ok.py (run with python3 -m unittest, or pytest when it is installed)'

/** The `.gitignore` ignores `name` (a plain folder name, with or without slashes). */
export const gitignored = (gitignore: string | undefined, name: string): boolean =>
  (gitignore ?? '').split(/\r?\n/).some(l => [name, `${name}/`, `/${name}`, `/${name}/`].includes(l.trim()))

/** Whether the mode is repo=here: no origin/main to cut worktrees from. */
export const isHereMode = (p: SetupProbe): boolean => !p.hasOriginMain

/** The base ref setup writes in repo=here mode. */
export const hereBaseRef = (p: SetupProbe): string => (p.branch && p.branch !== 'HEAD' ? p.branch : 'main')

/** The ordered checks: required first (1 to 6), then the advice (7 to 13). */
export function setupChecks(p: SetupProbe): SetupLine[] {
  const out: SetupLine[] = []
  const req = (ok: boolean, text: string, fix?: string): void => void out.push({ level: 'required', ok, text, ...(!ok && fix ? { fix } : {}) })
  const adv = (text: string, fix?: string): void => void out.push({ level: 'advice', ok: true, text, ...(fix ? { fix } : {}) })

  req(p.inRepo, p.inRepo ? 'a git repo' : 'a git repo: none here', 'git init -b main')
  const top = p.toplevel ? norm(p.toplevel) : undefined
  const atTop = p.inRepo && top === norm(p.root)
  req(
    atTop,
    atTop ? 'the session root is the repo top level' : p.inRepo ? `the session root is not the repo top level (${top ?? 'unknown'})` : 'the session root is the repo top level: no repo yet',
    p.inRepo ? `start Claude Code in ${top ?? 'the repo top level'}` : 'run git init -b main in this folder, which then is the top level',
  )
  req(p.hasCommit, p.hasCommit ? 'a first commit' : 'a first commit: none yet', 'git add -A && git commit -m "Initial commit"')

  const gate = detectGate(p)
  req(
    gate !== undefined,
    gate ? `a gate: ${gate.command}` : 'a gate: no test command found',
    `add a test command that passes on the empty project, then run /delegation setup again (${gateExample(p)})`,
  )

  const need = ['git', ...(gate?.stack === 'node' ? ['node', gate.pm ?? 'npm'] : gate?.stack === 'python' ? ['python3', ...(gate.runner === 'pytest' ? ['pytest'] : [])] : gate?.stack === 'rust' ? ['cargo'] : gate?.stack === 'go' ? ['go'] : [])]
  const missing = need.filter(t => !p.onPath.includes(t))
  req(missing.length === 0, missing.length === 0 ? `the tools on PATH: ${need.join(', ')}` : `the tools on PATH: missing ${missing.join(', ')}`, `install ${missing.join(', ')} and put it on PATH`)

  req(
    p.shadows.length === 0,
    p.shadows.length === 0 ? 'no shadowing command or skill' : `a command or skill shadows the mod: ${p.shadows.map(s => `~/${s}`).join(', ')}`,
    `remove ${p.shadows.map(s => `~/${s}`).join(' and ')}`,
  )

  if (p.hasOriginMain) adv('mode: worktree (origin/main resolves; each worker gets its own worktree)')
  else
    adv(
      `mode: repo=here (no origin/main); setup writes "baseRef": "${hereBaseRef(p)}" and cards dispatch with --here`,
      `or give worktree mode a remote: gh repo create ${base(p.root)} --private --source . --push (your call)`,
    )

  const lock = (['package-lock.json', 'pnpm-lock.yaml', 'yarn.lock', 'requirements.txt'] as const).find(l => has(p, l))
  adv(lock ? `a lockfile for the brief's install step: ${lock}` : "no lockfile (package-lock.json, pnpm-lock.yaml, yarn.lock, requirements.txt): the worker will have no install step")

  for (const child of p.childRepos.filter(c => gitignored(p.gitignore, c))) adv(`code in ${child} is its own repo; to delegate there, start Claude Code in ${child}`)

  if (has(p, '.claude-plugin/plugin.json')) adv(`a plugin repo: the cards go under ${PLUGIN_CARD_DIR}/`)

  adv(p.onPath.includes('gh') ? 'gh is on PATH: a report\'s pr= claim can be checked' : "gh is not on PATH: a report's pr= claim can be checked only with it")

  if (p.dirty && p.hasOriginMain) adv('uncommitted changes: in worktree mode they are not in a worker\'s worktree', 'commit them first')

  if (p.autoDebrief) adv('background debrief is on: it spends an agent at a quiet stop', 'turn it off: /delegation config autoDebrief false')
  return out
}

/** The count of required checks that hold, and the total. */
export const requiredTally = (lines: readonly SetupLine[]): { held: number; total: number } => {
  const r = lines.filter(l => l.level === 'required')
  return { held: r.filter(l => l.ok).length, total: r.length }
}

export const allRequiredHold = (lines: readonly SetupLine[]): boolean => {
  const t = requiredTally(lines)
  return t.held === t.total
}

/** Header, then one line per check, each fix indented under it. */
export function setupText(root: string, lines: readonly SetupLine[]): string {
  const t = requiredTally(lines)
  const out = [`chassis-delegation setup in ${root}: ${t.held} of ${t.total} required checks hold`]
  for (const l of lines) {
    out.push(`${l.level === 'advice' ? '·' : l.ok ? '✓' : '✗'} ${l.text}`)
    if (l.fix) out.push(`    ${l.level === 'required' ? 'fix: ' : ''}${l.fix}`)
  }
  return out.join('\n')
}

/** GH-116: the ceilings for a host whose gate deploys or runs tests remotely (sf, sfdx, deploy, --target-org, gcloud, aws, az, terraform); else the defaults. */
export function proposedSpend(gateCommands: string | readonly string[]): Record<'economy' | 'standard' | 'frontier', number> {
  const cmds = typeof gateCommands === 'string' ? [gateCommands] : gateCommands
  const cloud = cmds.some(c => /(^|[\s;&|(])(sf|sfdx|gcloud|aws|az|terraform)(\s|$)/.test(c) || /\bdeploy/i.test(c) || /--target-org\b/.test(c))
  return cloud ? { economy: 5, standard: 15, frontier: 35 } : { ...DEFAULT_SPEND_BY_TIER }
}

/** What setup found that the config should carry. */
export type Found = { gate: string; baseRef?: string; cardDir?: string; spendByTier?: Readonly<Record<'economy' | 'standard' | 'frontier', number>> }

export function foundOf(p: SetupProbe): Found {
  const gate = detectGate(p)
  return {
    gate: gate?.command ?? '',
    ...(isHereMode(p) ? { baseRef: hereBaseRef(p) } : {}),
    ...(has(p, '.claude-plugin/plugin.json') ? { cardDir: PLUGIN_CARD_DIR } : {}),
  }
}

/** The config template with what setup found filled in. Key order is the template's; baseRef goes last. */
export function scaffoldConfig(template: string, found: Found): string {
  const o = JSON.parse(template) as Record<string, unknown>
  o.gateMap = { test: found.gate }
  if (found.cardDir) o.cardDir = found.cardDir
  if (found.baseRef) o.baseRef = found.baseRef
  if (found.spendByTier) o.spendByTier = found.spendByTier
  return `${JSON.stringify(o, null, 2)}\n`
}

/** What setup would have set, when the config already exists and is left alone. */
export function wouldSet(found: Found): string {
  const parts = [`"gateMap": {"test": "${found.gate}"}`, ...(found.baseRef ? [`"baseRef": "${found.baseRef}"`] : []), ...(found.cardDir ? [`"cardDir": "${found.cardDir}"`] : [])]
  return `· ${REPO_CONFIG_FILE} exists and is left as it is; setup would have set ${parts.join(', ')}`
}

/** One line per key setup set in a fresh config. */
export function configLines(found: Found): string[] {
  const s = found.spendByTier
  const spend = s ? [`config: spendByTier = economy ${s.economy}, standard ${s.standard}, frontier ${s.frontier} (${s.standard === DEFAULT_SPEND_BY_TIER.standard ? 'the defaults' : 'the gate deploys or runs remote tests'})`] : []
  return [`config: gateMap.test = ${found.gate}`, ...(found.baseRef ? [`config: baseRef = ${found.baseRef}`] : []), ...(found.cardDir ? [`config: cardDir = ${found.cardDir}`] : []), ...spend]
}

/** A first task the person could say, by the detected stack. */
export function firstTaskExample(gate: Gate | undefined): string {
  const what = 'add a function that reads a file header and returns its size, with'
  if (!gate) return `${what} a test`
  if (gate.stack === 'python') return `${what} a unittest`
  if (gate.stack === 'node') return `${what} a node --test test`
  if (gate.stack === 'rust') return `${what} a cargo test`
  return `${what} a go test`
}

/**
 * What setup ends with: ask for the first task in a sentence; the brain writes
 * the card with the card tool. MOD-12: on go the brain dispatches and makes the
 * Agent call the dispatch returns; the mod shapes and verifies that worker.
 */
export const handoverText = (gate: Gate | undefined): string =>
  `Set up. Tell Claude your first task in a sentence, for example: "${firstTaskExample(gate)}". Claude writes the card, shows you the brief, and when you say go dispatches it and makes the Agent call that starts the worker; the mod shapes and verifies it.`

/** The extra line the setup tool (the brain) gets. */
export const BRAIN_HANDOVER = 'Ask the person for the first task, then call the card tool. On go, call dispatch and make the Agent call its result ends with (the spawn block, verbatim): that call starts the worker.'

files.hooks/lib/norepo.ts:
// Part 3A: a task with no git repo. A brief whose header says `repo=none`, or
// names a folder that is not a git work tree, has no branch, sha or diff for
// the native verifier (./verify-native.ts) to read. The mod checks three things only:
// every `files=` path of the report exists under the brief's first scope
// root; no such path lies outside the scope (or inside a forbid); and the
// gate exits 0. The gate resolves as for any brief (./gates.ts
// resolveGateRuns): the gate map's command for the header's `gate=` id, or the
// `gate=` itself when it is a bare command the allowlist takes (`claude plugin
// validate <absolute folder>`). Pure: no `$`, no imports.
//
// MOD-22, research cards: the second half of this file is what a card whose
// outputs live outside the repo adds, for repo=none and repo=here alike: the
// outdir, the roots to list, the before-and-after outside delta, the artefacts
// claim and the report's metrics. The listing and the stat themselves are the
// caller's (they are `$.fs` calls); everything decided here is pure.

/** `git -C <dir> rev-parse --is-inside-work-tree`: on the allowlist (rev-parse). */
export const workTreeArgv = (dir: string): string[] => ['git', '-C', dir, 'rev-parse', '--is-inside-work-tree']

/** A folder git does not know (exit ≠ 0), or the inside of a .git folder (`false`). */
export const isNotWorkTree = (r: { exitCode: number; stdout: string }): boolean => r.exitCode !== 0 || r.stdout.trim() === 'false'

const GLOB_CHARS = /[*?[{]/

/** The folder before a glob's first glob character; a path with none is its own root. */
export function globRoot(glob: string): string {
  const at = glob.search(GLOB_CHARS)
  if (at < 0) return glob.replace(/\/+$/, '') || '/'
  const head = glob.slice(0, at)
  return head.slice(0, head.lastIndexOf('/')) || '/'
}

/** `//` and `/./` folded; a `..` segment makes the path unusable (undefined). */
export function normalizePath(path: string): string | undefined {
  const parts = path.split('/')
  if (parts.includes('..')) return undefined
  const kept = parts.filter((p, i) => p !== '.' && (p !== '' || i === 0))
  const out = kept.join('/')
  return path.startsWith('/') ? out || '/' : out
}

/** A report path made absolute: relative ones are read against the scope root. */
export function resolveFile(file: string, root: string): string | undefined {
  return normalizePath(file.startsWith('/') ? file : `${root.replace(/\/+$/, '')}/${file}`)
}

const escapeRe = (s: string) => s.replace(/[.+^${}()|[\]\\]/g, '\\$&')

/** `**` spans folders (and `/**` matches the folder itself), `*` stays in one, `?` is one character, `{a,b}` either. */
export function globToRegExp(glob: string): RegExp {
  let re = ''
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i] as string
    if (c === '*') {
      if (glob[i + 1] === '*') {
        const slashAfter = glob[i + 2] === '/'
        const slashBefore = i > 0 && glob[i - 1] === '/'
        if (slashBefore && re.endsWith('\\/') && i + 2 === glob.length) {
          // `dir/**`: the folder itself or anything below it
          re = re.slice(0, -2) + '(?:\\/.*)?'
        } else if (slashAfter) {
          re += '(?:.*\\/)?'
          i += 1
        } else re += '.*'
        i += 1
      } else re += '[^/]*'
    } else if (c === '?') re += '[^/]'
    else if (c === '{') {
      const close = glob.indexOf('}', i)
      if (close < 0) re += '\\{'
      else {
        re += `(?:${glob.slice(i + 1, close).split(',').map(escapeRe).join('|')})`
        i = close
      }
    } else if (c === '/') re += '\\/'
    else re += escapeRe(c)
  }
  return new RegExp(`^${re}$`)
}

export const matchGlob = (path: string, glob: string): boolean => globToRegExp(glob).test(path)

/** The report's `files=` list: comma-separated, `none` and blanks dropped. */
export const reportFiles = (files: string | undefined): string[] =>
  (files ?? '').split(',').map(f => f.trim()).filter(f => f !== '' && f !== 'none' && f !== '-')

/** A brief's comma list (`scope=`, `forbid=`): blanks and `none` dropped. */
export const globList = (value: string | undefined): string[] =>
  (value ?? '').split(',').map(g => g.trim()).filter(g => g !== '' && g !== 'none')

export type ScopeResult = { inScope: string[]; outOfScope: string[]; forbidden: string[] }

/**
 * Each report file, made absolute against the scope root: in scope when a
 * scope glob matches it and no forbid glob does. A path that cannot be made
 * absolute (a `..` segment) is out of scope as written.
 */
export function scopeCheck(input: { files: readonly string[]; root: string; scope: readonly string[]; forbid: readonly string[] }): ScopeResult {
  const out: ScopeResult = { inScope: [], outOfScope: [], forbidden: [] }
  const abs = (g: string) => (g.startsWith('/') ? g : `${input.root}/${g}`)
  for (const file of input.files) {
    const path = resolveFile(file, input.root)
    if (path === undefined) out.outOfScope.push(file)
    else if (input.forbid.some(g => matchGlob(path, abs(g)))) out.forbidden.push(path)
    else if (input.scope.some(g => matchGlob(path, abs(g)))) out.inScope.push(path)
    else out.outOfScope.push(path)
  }
  return out
}

export type GateOutcome = { label: string; exitCode?: number; error?: string }

// ---- MOD-22: research cards ----------------------------------------------------------

export const isAbsolute = (entry: string): boolean => entry.startsWith('/')

/** A leading `~` or `~/` is the home folder; `~user`, a `~` elsewhere and an empty home are left as written. */
export function expandTilde(entry: string, home: string): string {
  const h = home.replace(/\/+$/, '')
  if (h === '') return entry
  if (entry === '~') return h
  return entry.startsWith('~/') ? `${h}${entry.slice(1)}` : entry
}

/** The card's output folder: the one it names (`outdir:`), else the folder of its first absolute scope entry. */
export function outdirOf(scope: readonly string[], named?: string): string | undefined {
  const n = (named ?? '').trim()
  if (n !== '') return n.replace(/\/+$/, '') || '/'
  const first = scope.find(isAbsolute)
  return first === undefined ? undefined : globRoot(first)
}

/** A path is under `root` (or is it). */
const under = (path: string, root: string): boolean => path === root || path.startsWith(root === '/' ? '/' : `${root}/`)

/** The roots with any that lies inside another dropped, each once, in order. */
const outermost = (roots: readonly string[]): string[] => {
  const all = [...new Set(roots)]
  return all.filter(r => !all.some(o => o !== r && under(r, o)))
}

/** The folders to list: the root of every absolute scope and forbid entry, each once, a root inside another dropped. */
export function outsideRoots(scope: readonly string[], forbid: readonly string[]): string[] {
  return outermost([...scope, ...forbid].filter(isAbsolute).map(globRoot))
}

/** The scratch folder a brief names by default: the system temp dir, then chassis-delegation/<task>. */
export const defaultScratch = (tmp: string, task: string): string => `${tmp.replace(/\/+$/, '') || '/tmp'}/chassis-delegation/${task}`

/** One file under a listed root: its path relative to the root, its size and its modification time. */
export type OutsideEntry = { path: string; size: number; mtimeMs: number }
/** A root's listing, or why it could not be made. */
/**
 * A root's listing, or why it could not be made. MOD-85: a root too big to list is recorded at dispatch
 * as a watermark (`since`, the ms time before its walk began, and `files`, the count walked); at hand-back
 * its walk holds only what is newer than `since`: the files in `entries`, the folders in `dirs` (path ''
 * is the root itself).
 */
export type RootListing =
  | { root: string; entries: OutsideEntry[]; dirs?: { path: string; mtimeMs: number }[] }
  | { root: string; error: string }
  | { root: string; since: number; files: number }
/** The most entries the hand-back walk of a watermark root visits before the claim is left unchecked. */
export const OUTSIDE_WALK_CEILING = 1000000
export type ClaimResult = { status: 'held' | 'failed' | 'unchecked'; detail: string }

const absOf = (root: string, rel: string): string => (root === '/' ? `/${rel}` : `${root}/${rel}`)
const anyMatch = (path: string, globs: readonly string[], dir = false): boolean => globs.some(g => isAbsolute(g) && (matchGlob(path, g) || (dir && matchGlob(`${path === '/' ? '' : path}/x`, g))))

/**
 * The scope claim for what changed outside the repo: every root in either
 * listing, before against after. A path added, removed or changed (size or
 * time) must match an absolute scope entry and no absolute forbid entry;
 * the first that does not fails the claim, named, with the delta it came from.
 * A root that was not listed at one end leaves the claim unchecked unless a
 * failure was found elsewhere. Undefined when no root was listed at all.
 */
export function outsideClaim(input: { before: readonly RootListing[]; after: readonly RootListing[]; scope: readonly string[]; forbid: readonly string[] }): ClaimResult | undefined {
  const roots = [...new Set([...input.before.map(l => l.root), ...input.after.map(l => l.root)])]
  if (roots.length === 0) return undefined
  const changed: string[] = []
  const changedDirs = new Set<string>()
  let watched = false
  let unchecked: string | undefined
  for (const root of roots) {
    const b = input.before.find(l => l.root === root)
    const a = input.after.find(l => l.root === root)
    if (b === undefined) unchecked ??= `outside delta: no listing of ${root} was taken at dispatch`
    else if ('error' in b) unchecked ??= `outside delta: ${root} could not be listed at dispatch: ${b.error}`
    else if ('since' in b) {
      if (a === undefined) unchecked ??= `outside delta: ${root} was not listed at hand-back`
      else if ('error' in a) unchecked ??= `outside delta: ${root} could not be listed at hand-back: ${a.error}`
      else if ('since' in a) unchecked ??= `outside delta: ${root} was not walked at hand-back`
      else {
        watched = true
        for (const e of a.entries) if (e.mtimeMs > b.since) changed.push(absOf(root, e.path))
        for (const d of a.dirs ?? []) if (d.mtimeMs > b.since) changedDirs.add(d.path === '' ? root : absOf(root, d.path))
      }
    } else if (a === undefined) unchecked ??= `outside delta: ${root} was not listed at hand-back`
    else if ('error' in a) unchecked ??= `outside delta: ${root} could not be listed at hand-back: ${a.error}`
    else if ('since' in a) unchecked ??= `outside delta: ${root} was not listed at hand-back`
    else {
      const was = new Map(b.entries.map(e => [e.path, e]))
      const now = new Map(a.entries.map(e => [e.path, e]))
      for (const [path, e] of now) {
        const o = was.get(path)
        if (o === undefined || o.size !== e.size || o.mtimeMs !== e.mtimeMs) changed.push(absOf(root, path))
      }
      for (const path of was.keys()) if (!now.has(path)) changed.push(absOf(root, path))
    }
  }
  const files = [...new Set(changed)].filter(p => !changedDirs.has(p))
  const paths = [...new Set([...files, ...changedDirs])].sort()
  const bad = paths.flatMap(p => {
    const dir = changedDirs.has(p)
    return anyMatch(p, input.forbid, dir) ? [{ p, why: 'touches forbid path' }] : anyMatch(p, input.scope, dir) ? [] : [{ p, why: 'out-of-scope path' }]
  })
  const first = bad[0]
  if (first) return { status: 'failed', detail: `${first.why}: ${first.p} (outside delta${bad.length > 1 ? `, +${bad.length - 1} more` : ''})` }
  if (unchecked !== undefined) return { status: 'unchecked', detail: unchecked }
  const where = roots.join(', ')
  const by = watched ? ' (checked by modification time)' : ''
  return { status: 'held', detail: paths.length === 0 ? `outside delta: nothing changed under ${where}${by}` : `outside delta: ${plural(paths.length, 'changed path')} under ${where}, every one within scope and none in forbid${by}` }
}

/** What the verifier needs to compare the outside: the listings taken at dispatch, and a way to list a root now. */
export type OutsideInput = { before: readonly RootListing[]; list: (root: string, since?: number) => Promise<RootListing> }

/**
 * Lists the roots again (those listed at dispatch and those the scope and forbid name now) and judges
 * the outside delta. Undefined when nothing was recorded at dispatch (a brief that never went through
 * /dispatch): the outside is then no part of the scope claim.
 */
export async function outsideCheck(scope: readonly string[], forbid: readonly string[], outside: OutsideInput | undefined): Promise<ClaimResult | undefined> {
  if (outside === undefined) return undefined
  // a root an amendment added inside a folder listed at dispatch is covered by that listing
  const roots = outermost([...outside.before.map(l => l.root), ...outsideRoots(scope, forbid)])
  const after: RootListing[] = []
  for (const root of roots) {
    try {
      const mark = outside.before.find(l => l.root === root)
      after.push(await outside.list(root, mark !== undefined && 'since' in mark ? mark.since : undefined))
    } catch (err) {
      after.push({ root, error: String(err) })
    }
  }
  return outsideClaim({ before: outside.before, after, scope, forbid })
}

/** The report's `artefacts=` list: comma-separated paths, `none` and blanks dropped. */
export const reportArtefacts = reportFiles

/** The report's `metrics="k=v,k=v"` as a record; an item without `=`, a repeated key and `__proto__` are dropped. */
export function reportMetrics(metrics: string | undefined): Record<string, string> {
  const out: Record<string, string> = {}
  for (const item of (metrics ?? '').split(',')) {
    const at = item.indexOf('=')
    const key = at > 0 ? item.slice(0, at).trim() : ''
    if (key === '' || key === '__proto__' || key in out || Object.keys(out).length >= 50) continue
    out[key] = item.slice(at + 1).trim().slice(0, 200)
  }
  return out
}

/** `metrics: tris=1200, len_s=2.4`: the verdict detail line (recorded, never judged). */
export const metricsLine = (m: Readonly<Record<string, string>>): string => `metrics: ${Object.entries(m).map(([k, v]) => `${k}=${v}`).join(', ')}`

/** What a stat of one artefact found. */
export type ArtefactStat = { exists: boolean; size?: number; isDir?: boolean; error?: string }
/** One named artefact: its absolute path (undefined when it cannot be made) and what was found there. */
export type ArtefactResult = { name: string; path?: string; exists?: boolean; size?: number; isDir?: boolean; error?: string }

/**
 * The artefacts claim: each named path exists and is not empty (a folder: has an entry). Fails naming
 * the first that is missing or empty; unchecked when one could not be read and none failed; undefined
 * when the report names none.
 */
export function artefactsClaim(results: readonly ArtefactResult[]): ClaimResult | undefined {
  if (results.length === 0) return undefined
  const shown = (r: ArtefactResult): string => (r.path === undefined || r.path === r.name ? r.name : `${r.name} (${r.path})`)
  let unread: ArtefactResult | undefined
  for (const r of results) {
    if (r.path === undefined) return { status: 'failed', detail: `missing: ${r.name} (a '..' segment names no path)` }
    if (r.error !== undefined) {
      unread ??= r
      continue
    }
    if (!r.exists) return { status: 'failed', detail: `missing: ${shown(r)}` }
    if ((r.size ?? 0) === 0) return { status: 'failed', detail: `empty: ${shown(r)}` }
  }
  if (unread) return { status: 'unchecked', detail: `could not be read: ${unread.name} (${unread.error})` }
  const size = (r: ArtefactResult): string => (r.isDir ? `${r.size ?? 0} ${r.size === 1 ? 'entry' : 'entries'}` : plural(r.size ?? 0, 'byte'))
  return { status: 'held', detail: `${results.length} ${results.length === 1 ? 'artefact exists and is' : 'artefacts exist and are'} not empty: ${results.map(r => `${r.name} (${size(r)})`).join(', ')}` }
}

/** Stats each named artefact (a relative one against `base`) through the caller's `stat`, and judges them. */
export async function artefactsCheck(names: readonly string[], base: string, stat: (path: string) => Promise<ArtefactStat>): Promise<ClaimResult | undefined> {
  const results: ArtefactResult[] = []
  for (const name of names) {
    const path = resolveFile(name, base)
    if (path === undefined) {
      results.push({ name, exists: false })
      continue
    }
    try {
      results.push({ name, path, ...(await stat(path)) })
    } catch (err) {
      results.push({ name, path, exists: false, error: String(err) })
    }
  }
  return artefactsClaim(results)
}

export type NoRepoInput = {
  root: string
  /** The report's files, absolute, that are in scope. */
  files: readonly string[]
  missing: readonly string[]
  outOfScope: readonly string[]
  forbidden: readonly string[]
  gates: readonly GateOutcome[]
  notRerun: readonly string[]
  noGate: boolean
  /** MOD-22: the outside delta's claim, part of the scope claim. */
  outside?: ClaimResult
  /** MOD-22: the artefacts claim, after files. */
  artefacts?: ClaimResult
  /** MOD-22: the report's metrics, shown on a line of their own and never judged. */
  metrics?: Readonly<Record<string, string>>
}

export type NoRepoVerdict = { verdict: 'consistent' | 'refuted' | 'unverified'; why?: string; lines: string[] }

const plural = (n: number, one: string) => `${n} ${one}${n === 1 ? '' : 's'}`

/**
 * The verdict and its claim lines, in the native verifier's shape
 * (`claim <name>: held|failed|unchecked — <detail>`). A failed claim refutes
 * (scope first, then missing files, then artefacts, then the gate); else an
 * unchecked one (a gate not re-run, none at all) leaves it unverified; else consistent.
 */
export function noRepoVerdict(v: NoRepoInput): NoRepoVerdict {
  const lines: string[] = []
  const failed: string[] = []
  const unchecked: string[] = []
  const filesScope: ClaimResult =
    v.outOfScope.length > 0 || v.forbidden.length > 0
      ? { status: 'failed', detail: v.outOfScope.length > 0 ? `out of scope: ${v.outOfScope.join(', ')}` : `forbidden: ${v.forbidden.join(', ')}` }
      : { status: 'held', detail: 'every file in scope' }
  const scopeParts = [filesScope, ...(v.outside ? [v.outside] : [])]
  const scopeFailed = scopeParts.filter(p => p.status === 'failed')
  if (scopeFailed.length > 0) {
    const why = scopeFailed.map(p => p.detail).join('; ')
    lines.push(`claim scope: failed — ${why}`)
    failed.push(why)
  } else if (v.outside?.status === 'unchecked') {
    lines.push(`claim scope: unchecked — ${v.outside.detail}`)
    unchecked.push(v.outside.detail)
  } else lines.push(`claim scope: held — ${scopeParts.map(p => p.detail).join('; ')}`)
  if (v.missing.length > 0) {
    const why = `missing: ${v.missing.join(', ')}`
    lines.push(`claim files: failed — ${why}`)
    failed.push(why)
  } else lines.push(`claim files: held — ${plural(v.files.length, 'file')} under ${v.root}`)
  if (v.artefacts) {
    lines.push(`claim artefacts: ${v.artefacts.status} — ${v.artefacts.detail}`)
    if (v.artefacts.status === 'failed') failed.push(v.artefacts.detail)
    else if (v.artefacts.status === 'unchecked') unchecked.push(v.artefacts.detail)
  }
  if (v.noGate) {
    lines.push('claim gate: unchecked — no gate= in the brief')
    unchecked.push('no gate= in the brief')
  }
  for (const g of v.gates) {
    if (g.error !== undefined) {
      const why = `gate ${g.label} did not run: ${g.error}`
      lines.push(`claim gate: unchecked — ${why}`)
      unchecked.push(why)
    } else if (g.exitCode === 0) lines.push(`claim gate: held — ${g.label} exited 0`)
    else {
      const why = `gate ${g.label} exited ${g.exitCode}`
      lines.push(`claim gate: failed — ${why}`)
      failed.push(why)
    }
  }
  for (const id of v.notRerun) {
    lines.push(`claim gate: unchecked — gate not re-run: ${id}`)
    unchecked.push(`gate not re-run: ${id}`)
  }
  if (v.metrics && Object.keys(v.metrics).length > 0) lines.push(metricsLine(v.metrics))
  if (failed.length > 0) return { verdict: 'refuted', why: failed[0] as string, lines }
  if (unchecked.length > 0) return { verdict: 'unverified', why: unchecked[0] as string, lines }
  return { verdict: 'consistent', lines }
}

/** `consistent (no repo)`, `refuted (no repo): <why>`, `unverified (no repo): <why>`. */
export const noRepoVerdictText = (v: { verdict: string; why?: string }): string =>
  `${v.verdict} (no repo)${v.why ? `: ${v.why}` : ''}`

