// Tier precedence and tier → alias mapping. Pure: no `$`.
//
// Precedence (SPEC part 1): the brief header's `tier=` (the contract; `model=`
// there is advisory) > the caller's explicit `model` > the classifier. A
// header without `tier=` floors at standard (the chassis default) and never
// asks the classifier. A respawn after a refuted attempt (or a confirmed
// gate=fail) is escalated one tier above that attempt (never below the brief's
// own tier); a respawn after a no-report is held at that attempt's tier (GH-104).

export type Tier = 'economy' | 'standard' | 'frontier' | 'premium'
export type Alias = 'haiku' | 'sonnet' | 'opus' | 'fable'
/** MOD-21: `review` is a reviewer's pick: one tier below the worker's (or the reviewTier option's). */
export type TierSource = 'brief' | 'caller' | 'classified' | 'floor' | 'escalated' | 'held' | 'resume' | 'review'
export type TierPick = { tier: Tier; source: TierSource; callerAlias?: Alias }

export const TIERS: readonly Tier[] = ['economy', 'standard', 'frontier', 'premium']
export const CLASSIFIER_LABELS = ['economy', 'standard', 'frontier'] as const

/** The built-in tier map (part 5B): a repo's `tierMap` (or /config) overrides it per tier. */
export const BUILTIN_TIER_MAP: Readonly<Record<Tier, Alias>> = {
  economy: 'haiku',
  standard: 'sonnet',
  frontier: 'opus',
  premium: 'fable',
}

/**
 * The classifier's label guide, from chassis/core/dispatch.md's tier table.
 * Exported so the classifier eval (tests/eval/classifier-cases.jsonl) runs against
 * exactly the text the mod sends.
 */
export const TIER_LABEL_GUIDE = [
  'You are choosing the model tier for a coding subagent from the task it is given.',
  'Answer with one label:',
  '- economy: mechanical work with an exact spec and a red test (bulk renames, fixture generation, log or screenshot triage, data seeding, reformatting). Nothing that needs judgment about project conventions.',
  '- standard: the default worker (feature implementation, test writing, refactors, end-to-end scenarios, standard debugging, read-only research). About 80% of tasks.',
  '- frontier: ambiguous debugging, architectural trade-offs, prompt engineering, cross-domain contracts, or anything the task itself is uncertain about.',
  'When unsure between two labels, answer the lower one unless the task is ambiguous or crosses domains.',
].join('\n')

const RANK: Record<Tier, number> = { economy: 0, standard: 1, frontier: 2, premium: 3 }

export const isTier = (x: unknown): x is Tier => typeof x === 'string' && (TIERS as readonly string[]).includes(x)

/** An alias or a full id → its family alias; undefined when it names no family. */
export function aliasOf(model: string | undefined): Alias | undefined {
  const m = /(haiku|sonnet|opus|fable)/.exec((model ?? '').toLowerCase())
  return m ? (m[1] as Alias) : undefined
}

/**
 * GH-108: what a card's `tier:` or a header's `tier=` means. The four tiers as
 * themselves; a model family (or a full id containing one) as its tier; anything
 * else undefined. Case-insensitive.
 */
export function tierOf(value: string | undefined): Tier | undefined {
  const v = (value ?? '').trim().toLowerCase()
  if (isTier(v)) return v
  const alias = aliasOf(v)
  return alias ? tierOfAlias(alias) : undefined
}

/** GH-108: the line for a tier written but unknown, which the mod runs at standard; undefined when absent or known. */
export function tierWarning(value: string | undefined): string | undefined {
  const v = (value ?? '').trim()
  if (v === '' || tierOf(v) !== undefined) return undefined
  return `warning: tier "${v}" is not economy, standard, frontier or premium; dispatched at standard`
}

export function tierOfAlias(alias: Alias): Tier {
  return alias === 'haiku' ? 'economy' : alias === 'sonnet' ? 'standard' : alias === 'opus' ? 'frontier' : 'premium'
}

/** economy → standard → frontier; frontier stays frontier; premium stays premium. */
export function nextTier(tier: Tier): Tier {
  return tier === 'economy' ? 'standard' : tier === 'standard' ? 'frontier' : tier
}

export const maxTier = (a: Tier, b: Tier): Tier => (RANK[a] >= RANK[b] ? a : b)

/**
 * MOD-21: the tier a reviewer runs at: one below the worker's (premium → frontier
 * → standard → economy, and economy stays economy: the floor), or `override`
 * (the reviewTier option) when one is set.
 */
export function reviewerTier(workerTier: Tier, override?: Tier): Tier {
  if (override) return override
  return workerTier === 'premium' ? 'frontier' : workerTier === 'frontier' ? 'standard' : 'economy'
}

export type PickInput = {
  hadHeader: boolean
  headerTier?: string
  callerModel?: string
  classified?: string
  escalateFrom?: Tier
  /** GH-104: a respawn after a no-report runs at least at this tier (that attempt's), never one up. */
  holdAt?: Tier
}

/**
 * The classifier is asked only when nothing else decides: no header (a header
 * with a tier is the contract, one without floors at standard) AND no
 * caller-model hint (GH-1 item 8: a call per delegation otherwise).
 */
export const needsClassifier = (input: Pick<PickInput, 'hadHeader' | 'headerTier' | 'callerModel'>): boolean =>
  !input.hadHeader && tierOf(input.headerTier) === undefined && !input.callerModel

export function pickTier(input: PickInput): TierPick {
  let pick: TierPick
  const headerTier = tierOf(input.headerTier)
  if (headerTier) pick = { tier: headerTier, source: 'brief' }
  else if (input.callerModel) {
    const callerAlias = aliasOf(input.callerModel)
    pick = callerAlias ? { tier: tierOfAlias(callerAlias), source: 'caller', callerAlias } : { tier: 'standard', source: 'floor' }
  } else if (input.hadHeader) pick = { tier: 'standard', source: 'floor' }
  else if ((CLASSIFIER_LABELS as readonly string[]).includes(input.classified ?? '')) pick = { tier: input.classified as Tier, source: 'classified' }
  else pick = { tier: 'standard', source: 'floor' }
  if (input.escalateFrom) {
    const up = nextTier(input.escalateFrom)
    if (RANK[up] > RANK[pick.tier]) pick = { tier: up, source: 'escalated' }
  }
  if (input.holdAt && RANK[input.holdAt] > RANK[pick.tier]) pick = { tier: input.holdAt, source: 'held' }
  return pick
}

/**
 * The alias the spawn gets: the caller's own family when the caller decided,
 * else the tier map's entry for the tier (an id is reduced to its alias), else
 * the built-in map. Fable is never a spawn target: it is rewritten to opus.
 */
export function finalAlias(pick: TierPick, mappedTo: string | undefined): { alias: Alias; fableRewritten: boolean } {
  const mapped = aliasOf(mappedTo)
  const alias: Alias = pick.source === 'caller' && pick.callerAlias ? pick.callerAlias : mapped ?? BUILTIN_TIER_MAP[pick.tier]
  return alias === 'fable' ? { alias: 'opus', fableRewritten: true } : { alias, fableRewritten: false }
}

/**
 * GH-1 item 8: fable was asked for — the tier map gave it (and it was
 * rewritten), or the brief's advisory `model=` names it — and the spawn runs
 * on opus. The caller naming fable reaches here as a rewrite.
 */
export const fableRequested = (alias: Alias, fableRewritten: boolean, headerModel?: string): boolean =>
  alias === 'opus' && (fableRewritten || aliasOf(headerModel) === 'fable')

/** A briefed spawn's place on its budget (GH-104): `attempt` of `budget`. */
export type AttemptOf = { attempt: number; budget: number }

/**
 * The notice under the spawn. When fable was requested and opus spawns, it
 * says so at the tier the spawn runs at (GH-1 item 8), so the rewrite
 * never hides a tier: `tier=frontier → opus (fable requested; …)`. A briefed
 * spawn's notice ends with its attempt (GH-104), so a spend is never a
 * surprise: `tier=standard → sonnet (brief) · attempt 2/3`.
 */
export function noticeText(pick: TierPick, alias: Alias, fableAsked: boolean, at?: AttemptOf): string {
  const tail = at ? ` · attempt ${at.attempt}/${at.budget}` : ''
  if (fableAsked && alias === 'opus') return `tier=${pick.tier === 'premium' ? 'frontier' : pick.tier} → ${alias} (fable requested; fable is never spawned by the mod)${tail}`
  return `tier=${pick.tier} → ${alias} (${pick.source})${tail}`
}

const PICKED_BY: Readonly<Record<TierSource, string>> = {
  brief: "the brief header's tier=",
  caller: "the caller's model hint",
  classified: 'the classifier',
  floor: 'the standard floor',
  escalated: 'escalation one tier above the last refuted attempt',
  held: "the last attempt's tier (a respawn after a no-report is held there, never escalated)",
  resume: 'the resumed spawn',
  review: "one tier below the reviewed worker's (or reviewTier)",
}

/**
 * The spawn's debug line (GH-1 item 8): which source picked the tier, and
 * whether the classifier was called for it.
 * `T-7: tier=economy picked by the brief header's tier= (no classify call)`.
 */
export function tierPickLine(label: string, tier: Tier, pick: TierPick, callerModel: string | undefined, classifyCalled: boolean): string {
  const by = pick.source === 'caller' && callerModel ? `${PICKED_BY.caller} (${callerModel})` : PICKED_BY[pick.source]
  return `${label}: tier=${tier} picked by ${by} (${classifyCalled ? 'classify called' : 'no classify call'})`
}

/** What the classifier reads: the guide, then the task, cut to keep the call small. */
export function classifierText(prompt: string): string {
  const cut = prompt.length > 6000 ? prompt.slice(0, 6000) + '\n[…cut]' : prompt
  return `${TIER_LABEL_GUIDE}\n\nThe task:\n${cut}`
}

// ---- MOD-13: the effort a worker steps at ----------------------------------------
/** The levels `turn.step` names (the engine's ModelEffort). */
export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'
export const EFFORTS: readonly Effort[] = ['low', 'medium', 'high', 'xhigh', 'max']
/** One entry of `effortByTier`: a level, or 0 / empty for the engine's own default. */
export type EffortSetting = Effort | 0 | ''
export type EffortTier = 'economy' | 'standard' | 'frontier'

/** Config `effortByTier` default: a standard card runs at medium, a frontier one at high. */
export const DEFAULT_EFFORT_BY_TIER: Readonly<Record<EffortTier, EffortSetting>> = { economy: 'low', standard: 'medium', frontier: 'high' }

const effortLevel = (v: unknown): Effort | undefined => {
  const s = typeof v === 'string' ? v.trim().toLowerCase() : ''
  return (EFFORTS as readonly string[]).includes(s) ? (s as Effort) : undefined
}
export const isEffort = (v: unknown): v is Effort => typeof v === 'string' && (EFFORTS as readonly string[]).includes(v)

/**
 * The effort a worker's `turn.step` is rewritten to: the card's own `effort:`
 * when it names a level (`0` there keeps the engine's), else the tier's entry
 * (premium reads the frontier's). Undefined: leave the engine's default.
 */
export function effortFor(tier: Tier, cardEffort: string | undefined, table: Readonly<Record<EffortTier, EffortSetting>>): Effort | undefined {
  const own = effortLevel(cardEffort)
  if (own) return own
  if (cardEffort?.trim() === '0') return undefined
  return effortLevel(table[tier === 'premium' ? 'frontier' : tier])
}

/** The `/delegation` line: `effort: economy low · standard medium · frontier high`. */
export const effortText = (table: Readonly<Record<EffortTier, EffortSetting>>): string =>
  `effort: ${(['economy', 'standard', 'frontier'] as const).map(t => `${t} ${effortLevel(table[t]) ?? 'default'}`).join(' · ')}`

files.hooks/lib/verify.ts:
// files.txt's place, the verdict and the escalation advice, and the lines the
// mod hands back. The verifier itself is ./verify-native.ts (part 5A); the gate
// map's rules are ./gates.ts. GH-104: the look at a worker's worktree before a
// respawn or an auto-resume, and the synthetic report `--verify` judges. Pure:
// no `$` (git runs through an injected `exec`).
import { extractReport } from './brief'
import { escalatesOn, ESCALATING_CLAIMS } from './attempts'
import { parseClaimLine, type ClaimLine } from './quiet'
import { nextTier, type Tier } from './tier'
import { BASE_REFS, type ExecOut } from './verify-native'

/**
 * `consistent` (MOD-19, renamed; see readRecord in ./attempts.ts) means every machine-checkable claim of the
 * report matches git. It is not a review: the brain still reads the diff.
 */
export type Verdict = 'consistent' | 'unverified' | 'refuted' | 'no-report' | 'refused'
/** MOD-56: the words of a usage-limit stop, matched case-insensitively (plus `429` in an HTTP or API sense, see HTTP_429) in a hand-back that has no [[report]] block. */
export const RATE_LIMIT_MARKERS: readonly string[] = ['hit your weekly limit', 'usage limit', 'rate limit', 'too many requests']

/** A `429` counts only in an HTTP or API sense: a whole word beside http, status, error, api or too many requests (never a sha, a line number or a count). */
const HTTP_429 = /\b(?:http|status|error|api)\b[\s:=#-]{0,3}(?<![\w.])429(?!\w)|(?<![\w.:])429(?!\w)[\s:,-]{0,3}(?:http\b|status\b|error\b|api\b|too many requests)/i

/**
 * MOD-56: a worker stopped by a usage limit. The turn.complete event carries no error text (its `reason` is
 * `error` and nothing more), so the hand-back text is read; and only when it holds no [[report]] block, so a
 * worker writing rate-limit code is never taken for a stopped one. `resetsAt` is the text after `resets`.
 */
export function detectRateLimit(text: string): { resetsAt?: string } | undefined {
  if (extractReport(text) !== undefined || text.includes('[[report')) return undefined
  const lower = text.toLowerCase()
  if (!RATE_LIMIT_MARKERS.some(m => lower.includes(m)) && !HTTP_429.test(text)) return undefined
  const m = /\bresets?\s+(?:at\s+|in\s+)?([^\n.]*?[^\s.])\s*(?:\.(?=\s|$)|\n|$)/i.exec(text)
  return m?.[1] ? { resetsAt: m[1].trim() } : {}
}

/** `no-report (rate limited[, resets <time>])`: the verdict as the row and the quiet line show it. */
export const rateLimitedVerdict = (rl: { resetsAt?: string }): string => `no-report (rate limited${rl.resetsAt ? `, resets ${rl.resetsAt}` : ''})`

/** A verdict as a caller holds it (a stored record is read through readRecord in ./attempts.ts first). */
export type StoredVerdict = Verdict

/** `<scratch>`: the folder holding the `briefs/` folder the brief sits in, else the brief's own folder. */
export function scratchFor(briefPath: string): string {
  const dir = briefPath.slice(0, briefPath.lastIndexOf('/')) || '/'
  return dir.endsWith('/briefs') ? dir.slice(0, -'/briefs'.length) || '/' : dir
}

export const filesPathFor = (scratch: string, task: string): string => `${scratch}/${task}/files.txt`

export const isFailing = (verdict: StoredVerdict, reportGate?: string): boolean =>
  verdict === 'refuted' || verdict === 'no-report' || reportGate === 'fail'

export type AdviceKind = 'accept' | 'review' | 'check' | 'fix-brief' | 'resume' | 'respawn' | 'verify' | 'exhausted' | 'none'
export type Advice = { kind: AdviceKind; next: string; tier?: Tier }

export type AdviseInput = {
  verdict: StoredVerdict
  reportGate?: string
  task: string
  attempts: number
  budget: number
  /** Resumes already made in the failing attempt's spawn lineage. */
  lineageResumes: number
  tier: Tier
  agentId?: string
  briefPath?: string
  adhoc: boolean
  /** GH-1 item 2: an ad hoc spawn (no header, no brief) whose report was checked cardlessly. */
  cardless?: boolean
  /** GH-115: the refuted attempt's first failed claim; read from `lines` when omitted. */
  firstFailed?: string
  /** The verifier's lines: an unverified verdict's resume names its unchecked claims (GH-1 item 5). */
  lines?: readonly string[]
  /**
   * MOD-21: a reviewer is due for a consistent verdict (the review option is on for this tier): the advice is
   * `review` where it would have been `accept`. Nothing else about the advice changes.
   */
  review?: boolean
}

/** An unchecked claim's reason is cut to this many characters in `next=`. */
export const PROVE_REASON_CAP = 160

const cutTo = (text: string, max: number): string => (text.length <= max ? text : `${text.slice(0, max - 1)}…`)

/** The verifier's `claim <name>: unchecked — <reason>` lines, as written. */
export const uncheckedClaimLines = (lines: readonly string[]): string[] => lines.filter(l => parseClaimLine(l)?.status === 'unchecked')

/** `gate (<reason>), red (<reason>)`: each unchecked claim's name and reason, the reason cut to 160 characters. */
export function proveList(lines: readonly string[]): string {
  return lines
    .map(parseClaimLine)
    .filter((c): c is ClaimLine => c?.status === 'unchecked')
    .map(c => `${c.name} (${cutTo(c.detail, PROVE_REASON_CAP)})`)
    .join(', ')
}

/** GH-115: a refuted verdict's first failed claim, as the verifier's lines name it. */
export const firstFailedClaim = (lines: readonly string[]): ClaimLine | undefined =>
  lines.map(parseClaimLine).find((c): c is ClaimLine => c?.status === 'failed')

/** The first path of a scope claim's `out-of-scope path: <path>` detail. */
const outOfScopePath = (c: ClaimLine): string | undefined => /out-of-scope path: (\S+)/.exec(c.detail)?.[1]

export const budgetDenyMessage = (label: string, attempts: number, briefPath?: string): string =>
  `budget exhausted for ${label} (${attempts} attempts); raise budget= in ${briefPath ?? "the task's brief"} to continue (the ladder resumes from attempt ${attempts}, the brief is re-read)`

/** MOD-55: whether the verifier's lines hold an `amend needs approval:` line whose block carries forbid-=. */
export const holdsForbidAmend = (lines: readonly string[]): boolean => lines.some(l => l.startsWith('amend needs approval:') && /\sforbid-=/.test(l))

/**
 * Resume-first escalation (SPEC amendment 1 B): the first failing verdict of
 * a spawn lineage resumes the same worker; the next one respawns with the
 * same brief, one tier up after a refuted report or a confirmed gate=fail, at
 * the SAME tier after a no-report (GH-104: a reporting defect, not a
 * capability one); a task at its budget stops. An unverified verdict with
 * unchecked claims, an agent and budget left resumes the worker to prove them
 * (GH-1 item 5); a cardless hand-back is never resumed or respawned. MOD-21: a
 * consistent verdict is advised `review` instead of `accept` when `review` is on.
 */
export function advise(input: AdviseInput): Advice {
  // a cardless hand-back has no brief to resume or respawn against (GH-1 item 2)
  if (input.adhoc && input.cardless) return input.verdict === 'consistent' && input.reportGate !== 'fail' ? { kind: 'accept', next: 'accept' } : { kind: 'check', next: 'check the diff' }
  if (input.adhoc) return { kind: 'none', next: 'none — ad hoc spawn, no brief' }
  if (input.verdict === 'consistent' && input.reportGate !== 'fail') return input.review ? { kind: 'review', next: 'review' } : { kind: 'accept', next: 'accept' }
  if (input.verdict === 'refused') return { kind: 'fix-brief', next: 'fix the brief — the verifier refused it (not charged to the worker)' }
  if (!isFailing(input.verdict, input.reportGate)) {
    // GH-1 item 5: unverified is actionable — resume the worker with the claims it has to prove
    const prove = proveList(input.lines ?? [])
    // MOD-59: a red file with no failure marker is one the worker cannot change by a resume; look at it
    const unchecked = uncheckedClaimLines(input.lines ?? []).map(parseClaimLine)
    const only = unchecked.length === 1 ? unchecked[0] : undefined
    const noMarker = only?.name === 'red' ? /^no failure marker found in red=(\S+) \(\d+ bytes\)/.exec(only.detail) : null
    if (noMarker && input.reportGate === 'pass') {
      const resume = input.agentId && input.attempts < input.budget ? `; else resume agent=${input.agentId} — prove: red` : ''
      return { kind: 'check', next: `check red by hand — no failure marker in ${noMarker[1]}; if it shows the red state, accept${resume}` }
    }
    if (prove !== '' && input.agentId && input.attempts < input.budget) return { kind: 'resume', next: `resume agent=${input.agentId} — prove: ${prove}` }
    return { kind: 'check', next: 'check by hand — unverified is not a pass' }
  }
  if (input.attempts >= input.budget) return { kind: 'exhausted', next: `stop — ${budgetDenyMessage(input.task, input.attempts)}` }
  // GH-115: a scope or files refute says the brief's globs are wrong, not that the worker was out of its depth
  const failed = input.verdict === 'refuted' ? firstFailedClaim(input.lines ?? []) : undefined
  const failedName = input.verdict === 'refuted' ? (input.firstFailed ?? failed?.name) : undefined
  const held = failedName !== undefined && !ESCALATING_CLAIMS.includes(failedName) ? failedName : undefined
  // MOD-55: a gate failure only a forbidden file can fix: the worker asked for forbid-= in an amend; the brain approves it (or refuses), then the fix is made
  if (holdsForbidAmend(input.lines ?? []) && (input.reportGate === 'fail' || failedName === 'gate')) {
    const at = input.briefPath ?? 'the brief'
    if (input.agentId) return { kind: 'resume', next: `approve the amend (append it to ${at}), then resume agent=${input.agentId} to make the fix; or refuse it` }
    const brief = input.briefPath ? `same brief ${input.briefPath}` : 'same prompt'
    return { kind: 'respawn', tier: input.tier, next: `approve the amend (append it to ${at}), then respawn at ${input.tier} — ${brief}, make the spawn block below (it names the model); or refuse it` }
  }
  if (input.lineageResumes === 0 && input.agentId) {
    if (held === 'scope') {
      const path = failed && failed.name === 'scope' ? outOfScopePath(failed) : undefined
      const amend = `[[amend v=1 scope+=${path ?? '<path>'} reason=…]]`
      // MOD-22: a stray file outside the repo is first a file to remove (a card keeps scratch out of its folders)
      const fix = failed?.detail.includes('(outside delta') ? `remove ${path ?? '<path>'}, or amend: ${amend}` : `amend: ${amend}`
      return { kind: 'resume', next: `resume agent=${input.agentId} — ${fix} (the path is outside scope; a scope refute never escalates)` }
    }
    if (held === 'files') return { kind: 'resume', next: `resume agent=${input.agentId} — list the paths named above in files= (or revert the extras)` }
    return { kind: 'resume', next: `resume agent=${input.agentId} — SendMessage it the verifier lines below` }
  }
  const tier = escalatesOn(input.verdict, input.reportGate) && held === undefined ? nextTier(input.tier) : input.tier
  const brief = input.briefPath ? `same brief ${input.briefPath}` : 'same prompt'
  const heldNote = held !== undefined && (held === 'scope' || held === 'files') ? ` (held: a ${held} refute)` : ''
  return { kind: 'respawn', tier, next: `respawn at ${tier} — ${brief}, make the spawn block below (it names the model)${heldNote}` }
}

// ---- GH-104: look before you respawn ---------------------------------------------

/** Finished work in a worker's worktree: its branch head, the branch, and the commits it is ahead of the base. */
export type WorkPresent = { sha: string; branch: string; ahead: number }
export type WorkProbe = ({ present: true } & WorkPresent) | { present: false; why: string }
export type GitExec = (argv: readonly string[], init?: { cwd?: string; timeoutMs?: number }) => Promise<ExecOut>

const GIT_READ_MS = 15 * 1000
const HEX_SHA = /^[0-9a-f]{7,64}$/i

/** Two spellings of one commit: one a prefix (7 hex at least) of the other. */
export function sameCommit(a: string, b: string): boolean {
  const x = a.trim().toLowerCase()
  const y = b.trim().toLowerCase()
  if (!HEX_SHA.test(x) || !HEX_SHA.test(y)) return false
  return x.length <= y.length ? y.startsWith(x) : x.startsWith(y)
}

/** `work present at <short sha> on <branch>: verify it (next=verify sha=<sha>)`: the line the row and the refusal carry. */
export const workPresentLine = (w: Pick<WorkPresent, 'sha' | 'branch'>): string => `work present at ${w.sha.slice(0, 7)} on ${w.branch}: verify it (next=verify sha=${w.sha})`

/** The advice when work is present: judge it, spawn nothing. */
export const verifyAdvice = (w: Pick<WorkPresent, 'sha'>): Advice => ({ kind: 'verify', next: `verify sha=${w.sha}` })

/** A respawn refused because work is present (the spawn hook's deny). */
export const workPresentDeny = (label: string, task: string, w: Pick<WorkPresent, 'sha' | 'branch'>): string =>
  `chassis-delegation: ${label} not spawned — ${workPresentLine(w)}; /dispatch ${task} --verify ${w.sha} runs the verifier on it (no spawn)`

/** True for that deny (the scheduler's drain posts it as a row). */
export const isWorkPresentDeny = (deny: string): boolean => / not spawned — work present at [0-9a-f]+ on /.test(deny)

/** The delta's base: `preferred` (a replay's base, the brief's base=, the config's baseRef), else the first of BASE_REFS that resolves. */
async function resolveBase(out: (...args: string[]) => Promise<string | undefined>, preferred?: string): Promise<string | undefined> {
  if (preferred && preferred.trim()) return preferred.trim()
  for (const ref of BASE_REFS) if ((await out('rev-parse', '--verify', '--quiet', ref)) !== undefined) return ref
  return undefined
}

const gitIn = (repo: string, exec: GitExec) => async (...args: string[]): Promise<string | undefined> => {
  const r = await exec(['git', '-C', repo, ...args], { cwd: repo, timeoutMs: GIT_READ_MS })
  return r.ok && r.exitCode === 0 ? r.stdout : undefined
}
const firstLineOf = (s: string | undefined): string => (s ?? '').split('\n')[0]?.trim() ?? ''

/**
 * GH-104: before a respawn or an auto-resume, the worker's worktree is read
 * with allowlisted git reads only (rev-parse, status, log). Work is present
 * when HEAD is not a sha the verifier already judged (`judged`), the tree is
 * clean, and HEAD has commits ahead of the base.
 */
export async function probeWork(input: { repo: string; base?: string; judged?: readonly string[] }, exec: GitExec): Promise<WorkProbe> {
  const out = gitIn(input.repo, exec)
  const head = firstLineOf(await out('rev-parse', 'HEAD'))
  if (!HEX_SHA.test(head)) return { present: false, why: `could not read HEAD in ${input.repo}` }
  if ((input.judged ?? []).some(j => sameCommit(j, head))) return { present: false, why: `HEAD ${head.slice(0, 7)} is a sha already judged` }
  const status = await out('status', '--porcelain')
  if (status === undefined) return { present: false, why: `git status failed in ${input.repo}` }
  const dirty = status.split('\n').filter(l => l.trim() !== '').length
  if (dirty > 0) return { present: false, why: `${dirty} uncommitted path${dirty === 1 ? '' : 's'} in the worktree` }
  const base = await resolveBase(out, input.base)
  if (!base) return { present: false, why: 'no base to count commits from' }
  const log = await out('log', '--format=%H', `${base}..HEAD`)
  if (log === undefined) return { present: false, why: `git log ${base}..HEAD failed in ${input.repo}` }
  const ahead = log.split('\n').filter(l => l.trim() !== '').length
  if (ahead === 0) return { present: false, why: `no commits ahead of ${base}` }
  const ref = firstLineOf(await out('rev-parse', '--abbrev-ref', 'HEAD'))
  return { present: true, sha: head, branch: ref && ref !== 'HEAD' ? ref : '(detached HEAD)', ahead }
}

/**
 * GH-104, `--verify`: the paths changed between merge-base(base, sha) and the
 * sha, as the verifier takes the delta (the same base chain).
 */
export async function branchDelta(input: { repo: string; sha: string; base?: string }, exec: GitExec): Promise<{ files: string[]; base: string } | { why: string }> {
  const out = gitIn(input.repo, exec)
  if ((await out('rev-parse', '--verify', '--quiet', `${input.sha}^{commit}`)) === undefined) return { why: `sha ${input.sha} does not resolve in ${input.repo}` }
  const base = await resolveBase(out, input.base)
  if (!base) return { why: `no base to take the delta from in ${input.repo}` }
  let mb = firstLineOf(await out('merge-base', base, input.sha))
  if (!mb && (await out('rev-parse', '--verify', '--quiet', base)) !== undefined) mb = base
  if (!mb) return { why: `no merge-base of ${base} and ${input.sha} in ${input.repo}` }
  const diff = await out('diff', '--no-renames', '--name-only', mb, input.sha)
  if (diff === undefined) return { why: `git diff ${mb.slice(0, 9)} ${input.sha} failed in ${input.repo}` }
  return { files: diff.split('\n').map(l => l.trim()).filter(Boolean), base }
}

/** The newest red file among a folder's names (`red-<n>.txt`, the highest n), or undefined. */
export function newestRed(names: readonly string[]): string | undefined {
  let best: { n: number; name: string } | undefined
  for (const name of names) {
    const m = /^red-(\d+)\.txt$/.exec(name)
    if (m && (!best || Number(m[1]) > best.n)) best = { n: Number(m[1]), name }
  }
  return best?.name
}

/**
 * GH-104: the report `--verify` hands the verifier for work no report came
 * with: the branch head, its delta as files=, gate=pass (the verifier re-runs
 * the gate, so a red one refutes), and the newest red file when there is one.
 */
export function syntheticReport(r: { task: string; subtask: string; branch: string; sha: string; files: readonly string[]; red?: string }): string {
  return (
    `[[report v=1 task=${r.task} subtask=${r.subtask} branch=${r.branch} pr=none sha=${r.sha} gate=pass` +
    `${r.red ? ` red=${r.red}` : ''} files=${r.files.length > 0 ? r.files.join(',') : 'none'}]]`
  )
}

/**
 * The verdict row's first line. `usd` (the attempt's cost, 2 decimals) and the
 * resolved `model` show when known; `next=` stays last because it runs to the
 * end of the line.
 */
export const verdictLine = (v: { verdict: Verdict; task: string; attempt: number; budget: number; next: string; usd?: number; usdApprox?: boolean; model?: string }): string =>
  `chassis-delegation: verdict=${v.verdict} task=${v.task} attempt=${v.attempt}/${v.budget}` +
  (v.usd !== undefined && Number.isFinite(v.usd) ? ` usd=${v.usdApprox ? '~' : ''}${v.usd.toFixed(2)}` : '') +
  (v.model ? ` model=${v.model}` : '') +
  ` next=${v.next}`

/** One line per amend the mod appended to the brief before verifying. */
export const amendedLine = (a: { ops: readonly string[]; reason: string }): string => `amended: ${a.ops.join(' ')} (reason ${a.reason})`

/** applyAmends off: the block, verbatim, and how to accept it. */
export const amendPendingLine = (a: { block: string }, briefPath: string): string =>
  `amend not applied (applyAmends off): ${a.block} — append it to ${briefPath} and re-verify to accept it`

/** A block that removes scope or a forbid: never appended on the worker's word. */
export const amendApprovalLine = (a: { block: string }, briefPath: string): string =>
  `amend needs approval: ${a.block} — append it to ${briefPath} and re-verify to accept it`

/** A hand-back block the verifier grammar refuses: never appended. */
export const amendMalformedLine = (m: { block: string; why: string }): string => `amend not applied (malformed: ${m.why}): ${m.block}`

/** The verdict line, then the verifier's lines, 40 lines at most. */
export function contextBlock(line: string, lines: readonly string[], cap = 40): string {
  if (lines.length + 1 <= cap) return [line, ...lines].join('\n')
  const keep = lines.slice(0, cap - 2)
  return [line, ...keep, `… ${lines.length - keep.length} more verifier lines cut`].join('\n')
}

/** True for the resume of an unverified hand-back that failed nothing (GH-1 item 5): it is asked to prove, not to fix. */
export const isProveResume = (verdict: Verdict, reportGate?: string): boolean => verdict === 'unverified' && !isFailing(verdict, reportGate)

/**
 * What a resume sends the worker. A prove resume (GH-1 item 5) carries
 * only the unchecked claim lines and asks the worker to prove them.
 */
export function resumeText(v: { verdict: Verdict; task: string; attempt: number; budget: number; lines: readonly string[]; prove?: boolean }): string {
  if (v.prove) {
    return [
      `chassis-delegation: your hand-back for ${v.task} (attempt ${v.attempt}/${v.budget}) came back unverified. These claims could not be checked:`,
      ...uncheckedClaimLines(v.lines),
      'Prove each one in the same worktree (commit what is uncommitted, name the evidence the claim needs), re-run the gate, and end with a fresh [[report v=1 …]] line.',
    ].join('\n')
  }
  return [
    `chassis-delegation: your hand-back for ${v.task} (attempt ${v.attempt}/${v.budget}) came back ${v.verdict}. The verifier said:`,
    ...v.lines,
    'Fix what failed in the same worktree, re-run the gate, commit, and end with a fresh [[report v=1 …]] line.',
  ].join('\n')
}

